return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'sv_SE','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-21T23:33:36+00:00','po-revision-date'=>'2026-07-05 23:26+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Flerspråkig routing, komplett flerspråkig SEO (hreflang, Open Graph, Schema.org, sitemap), och AI-innehållsverktyg för WordPress. Språkdetektion, URL-routing, översättning, innehållsgenerering och ett komplett SEO-lager — inget medföljande plugin krävs.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Översätt','Lingua Forge — Quick Translate'=>'Lingua Forge — Snabb översättning','Informative'=>'Informativ','Persuasive'=>'Övertygande','Storytelling'=>'Berättande','Technical'=>'Teknisk','Conversational'=>'Konversativ','Permission denied.'=>'Tillstånd nekad.','Cannot determine target language from slug.'=>'Kan inte bestämma målspråk från slug.','Invalid post type.'=>'Ogiltig inläggstyp.','Invalid or primary language.'=>'Ogiltigt eller primärt språk.','Template not found or not stored in the database.'=>'Mall inte hittad eller inte lagrad i databasen.','Template has no content.'=>'Mallen har inget innehåll.','No internal links found to update.'=>'Inga interna länkar att uppdatera.','%d link updated.'=>'%d länk uppdaterad.' . "\0" . '%d länkar uppdaterade.','No language-specific template parts found to map.'=>'Inga språkspecifika malldelar att mappa.','No template part references needed updating.'=>'Inga malldelarreferenser att uppdatera.','%d part reference updated.'=>'%d delreferens uppdaterad.' . "\0" . '%d delreferenser uppdaterade.','Invalid language.'=>'Ogiltigt språk.','Template part not found or not stored in the database.'=>'Malldel inte hittad eller inte lagrad i databasen.','Template part has no content.'=>'Malldel har inget innehåll.','No navigation references needed updating.'=>'Inga navigationsreferenser att uppdatera.','%d navigation reference updated.'=>'%d navigationsreferens uppdaterad.' . "\0" . '%d navigationsreferenser uppdaterade.','No AI provider configured.'=>'Ingen AI-leverantör konfigurerad.','Missing pattern name or language.'=>'Saknas mönsternamn eller språk.','Pattern not found.'=>'Mönster inte hittat.','Pattern has no content to translate.'=>'Mönster har inget att översätta.','AI provider returned an empty response.'=>'AI-leverantören returnerade ett tomt svar.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Mönster översatt och sparat. Kopiera innehållet till ditt CPT-inlägg via blockredigerarens mönsterinsättare eller använd det som utgångspunkt för ett återanvändbart block.','%d template repaired.'=>'%d mall reparerad.' . "\0" . '%d mallar reparerade.','All template metadata is already up to date.'=>'All mallmetadata är redan uppdaterad.','Invalid template type.'=>'Ogiltig malltyp.','Template "%s" already exists.'=>'"%s" finns redan.','Fix Links'=>'Fixa länkar','Fix Parts'=>'Fixa delar','Re-create'=>'Återskapa','"%s" recreated.'=>'"%s" återskapades.','"%s" created.'=>'"%s" skapad.','Invalid template part.'=>'Ogiltig malldel.','Template part "%s" already exists.'=>'Malldel "%s" finns redan.','Fix Nav'=>'Fixa navigation','"%1$s" recreated. %2$d template updated.'=>'"%1$s" återskapades. %2$d mall uppdaterad.' . "\0" . '%2$d mall uppdaterad.','"%1$s" created. %2$d template updated.'=>'"%1$s" skapad. %2$d mallar uppdaterade.' . "\0" . '"%1$s" skapad. %2$d mallar uppdaterade.','Page'=>'Sida','Single'=>'Enkel','Search'=>'Sök','Search Results'=>'Sökresultat','Archive'=>'Arkiv','Front Page'=>'Förstasida','Blog Home'=>'Blogg Hem','Single: %s'=>'Enskild: %s','Single %s'=>'Enskild %s','Archive: %s'=>'Arkiv: %s','%s Archive'=>'%s Arkiv','No source content found to translate.'=>'Hittade ingen källinnehåll att översätta.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Översatt. Granska i Webbplatsredigeraren — interna länkar, navigerings-URL:er och mall-sluggar uppdateras inte automatiskt.','Navigation not found.'=>'Navigering inte hittad.','Navigation has no content to translate.'=>'Navigering har inget innehåll att översätta.','"%1$s %2$s" saved.'=>'"%1$s %2$s" sparad.','SEO Analysis'=>'SEO-analys','Profile'=>'Profil','Details ↗'=>'Detaljer ↗','/ 100'=>'/ 100','Overall SEO score'=>'Samlat SEO-poäng','Metric'=>'Mått','Finding'=>'Hittar','Title'=>'Titel','Meta description'=>'Meta-beskrivning','Word count'=>'Ordräkning','Reading time'=>'Lästid','Headings'=>'Rubriker','Images'=>'Bilder','Links'=>'Länkar','AI Recommendations'=>'AI-rekommendationer','Run AI Analysis'=>'Kör AI-analys','Analyzing…'=>'Analyserar…','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Konfigurera en AI-leverantör i Inställningar → API-nycklar för att aktivera AI-drivna rekommendationer.','AI analysis failed. Please try again.'=>'AI-analysen misslyckades. Försök igen.','Suggested title'=>'Föreslagen titel','Suggested meta description'=>'Föreslagen meta-beskrivning','Loaded from cache.'=>'Laddad från cache.','↺ Refresh AI Analysis'=>'↺ Uppdatera AI-analys','Analyse…'=>'Analysera…','Analysis request failed. Please try again.'=>'Analysförfrågan misslyckades. Försök igen.','No translation found — analyzed the source language version.'=>'Ingen översättning hittades — analyserade källspråkversionen.','Translate page…'=>'Översätt sida…','Generate content…'=>'Generera innehåll…','AI Behaviour Preset'=>'AI-beteendepreset','Custom'=>'Anpassad','Global default (%s)'=>'Global standard (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Överskrider AI-preset för översättning och innehållsgenerering på denna sida. Inställningar för anpassade instruktioner (Inställningar → Beteende) läggs alltid till varje förfrågan oavsett detta val.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Överskrider AI-preset för översättning och innehållsgenerering på denna sida. Alla andra funktioner använder alltid den globala presetten.','Close'=>'Stäng','Translate missing'=>'Saknar översättning','From'=>'Från','Retranslate'=>'Omarbeta','Retranslate every other language version from this post. Creates any that are missing and overwrites any that already exist — including the primary language, if this post is a translation.'=>'Översätt varje annan språkversion från det här inlägget. Skapar eventuella som saknas och skriver över eventuella som redan finns – inklusive det primära språket, om det här inlägget är en översättning.','Sync'=>'Synkronisera','Reassign the correct language-specific template to every existing translation of this post. No AI call and no content changes — free and safe to run any time.'=>'Tilldela rätt språkspecifik mall till varje befintlig översättning av det här inlägget. Ingen AI-anrop och inga innehållsändringar – kostnadsfritt och säkert att köra när som helst.','Template Sync — reassign templates for every translation'=>'Mall-synkronisering – tilldela mallar för varje översättning','TS'=>'MS','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Senaste SEO-poäng baserat på regler. Kör analys i Inställningar → SEO → Analys för att uppdatera.','Translating…'=>'Översätter…','Retranslating…'=>'Omarbetar…','Syncing…'=>'Synkroniserar…','This retranslates every other language version of this post from this one — creating any that are missing and overwriting any that already exist (including the primary language, if this post is a translation). This cannot be undone. Continue?'=>'Detta översätter varje annan språkversion av det här inlägget från det här – skapar eventuella som saknas och skriver över eventuella som redan finns (inklusive det primära språket, om det här inlägget är en översättning). Detta kan inte ångras. Fortsätta?','Syncing templates…'=>'Synkroniserar mallar…','✓ Done'=>'✓ Klart','Error'=>'Fel','Navigation posts are translated via the Router tab, not this button.'=>'Navigeringsinlägg översätts via Routern-fliken, inte denna knapp.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Skapa översättningar för inläggstyp "%s" kräver en aktiv integration. Se till att den nödvändiga integrationen är installerad och aktiv.','No %s version found in this translation group.'=>'Ingen %s-version hittades i denna översättningsgrupp.','Sync from a secondary-language WooCommerce product is disabled by default, since it would overwrite the primary product. Enable it in Settings → Behavior → WooCommerce if you want a translation to be able to become the new source content.'=>'Synkronisering från en sekundärspråkig WooCommerce-produkt är inaktiverad som standard, eftersom det skulle skriva över den primära produkten. Aktivera det i Inställningar → Beteende → WooCommerce om du vill att en översättning ska kunna bli det nya källinnehållet.','Sync from a secondary-language post is disabled by default, since it would overwrite the primary post. Enable it in Settings → Behavior → Sync if you want a translation to be able to become the new source content.'=>'Synkronisering från ett sekundärspråkigt inlägg är inaktiverad som standard, eftersom det skulle skriva över det primära inlägget. Aktivera det i Inställningar → Beteende → Synkronisering om du vill att en översättning ska kunna bli det nya källinnehållet.','Skipped — you do not have permission to edit the existing translation.'=>'Överhoppad – du har inte behörighet att redigera den befintliga översättningen.','Creating translations for post type "%s" requires an active integration.'=>'Att skapa översättningar för inläggstypen "%s" kräver en aktiv integration.','Template Sync can only be run from the primary/source-language post.'=>'Mall-synkronisering kan bara köras från det primära/källspråkiga inlägget.','Skipped — you do not have permission to edit this translation.'=>'Överhoppad – du har inte behörighet att redigera denna översättning.','Translation Caching'=>'Översättningscaching','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge använder två oberoende cache-lager för att undvika redundanta AI-API-anrop. Använd flikarna nedan för att inspektera och hantera varje.','API Response Cache'=>'API-svarscache','Translation Memory'=>'Översättningsminne','(disabled)'=>'inaktiverad','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Per-inlägg cache för AI-genererade översättningar, meta-beskrivningar, utdrag och innehåll. Poster inaktiveras automatiskt när innehållet eller AI-leverantören/modellen ändras.','Enable API response caching'=>'Aktivera API-svarscaching','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'API-svarscachen lagrar det råa resultatet av varje AI-förfrågan — översättning, meta-beskrivning, utdrag och innehållsgenerering — nyckelordet är en hash av indata (innehåll, språkpar, leverantör, modell). Inaktivera under promptjustering eller när du behöver att varje förfrågan når AI-leverantören. Att inaktivera tar inte bort cache-inlägg — att återaktivera återställer dem.','Save'=>'Spara','Cached API responses'=>'Cachade API-svar','API calls saved by cache'=>'API-anrop sparade av cache','(avg %.1f hits/entry)'=>'(genomsnitt %.1f träffar/post)','Oldest cached response'=>'Äldsta cachade svar','Most recent cached response'=>'Senaste cachade svar','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Rensa alla cachade AI-resultat? Framtida förfrågningar kommer att utlösa nya API-anrop tills cachen byggs om.','Clear API Response Cache'=>'Rensa API-svarscachen','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Blocknivå-översättningscache delas mellan inlägg. När den är aktiverad, serveras identiska block (samma markup, språkpar och ordlista) från minnet istället för att anropa AI igen. Ändringar i ordlistan och ändringar i förinställningar för efterlevnad inaktiverar automatiskt cachelagrade översättningar.','Enable block-level translation cache reuse across posts'=>'Aktivera blocknivå-cacheåteranvändning över inlägg','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'För närvarande hoppar den över inlägg som använder block-kommentar attributplatshållare (wp:details sammanfattningsfält, etc.) — de faller igenom till den befintliga enkel-anropsöversättningsvägen.','Cached block translations'=>'Cachade blocköversättningar','Block translation reuses'=>'Blocköversättningsanvändningar','(avg %.1f hits/block)'=>'(genomsnitt %.1f träffar/block)','Oldest cached block'=>'Äldsta cachade block','Most recent cached block'=>'Senaste cachade block','Approximate size'=>'Ungefärlig storlek','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Rensa hela översättningstextminnet? Framtida översättningar kommer att bygga om cachen när de körs.','Clear Translation Memory'=>'Rensa översättningstextminne','API Response Cache setting saved.'=>'API-svarscache-inställning sparad.','Translation Memory setting saved.'=>'Inställningen för översättningstextminne sparad.','AI cache cleared. %d entry was removed.'=>'AI-cache rensad. %d post togs bort.' . "\0" . 'AI-cache rensad. %d poster togs bort.','Translation Memory cleared. %d cached block was removed.'=>'Översättningstextminne rensat. %d cachade block togs bort.' . "\0" . 'Översättningstextminne rensat. %d cachade block togs bort.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge är en komplett flerspråkig SEO-lösning. Inget ytterligare SEO-plugin krävs.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Om du har ett allmänt SEO-plugin installerat, visar detta panel hur LF anpassar sig för att undvika duplicerad utdata. Målet är att undvika kollision — inte samarbete. LF tillhandahåller alltid det flerspråkiga SEO-lagret (hreflang, og:locale, inLanguage-schema) som kräver kunskap om LF:s språkroutningskonfiguration för att producera korrekt.','Installed SEO plugins'=>'Installerade SEO-plugins','Plugin'=>'Plugin','Status'=>'Status','✓ Active'=>'✓ Aktiv','— Not detected'=>'— Inte upptäckt','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Inga konflikterande SEO-plugins upptäckta. Lingua Forge hanterar all SEO-output självständigt.','What LF provides — and collision avoidance'=>'Vad LF tillhandahåller — och kollisionsundvikande','Feature'=>'Funktion','LF provides'=>'LF tillhandahåller','When another SEO plugin is installed'=>'När ett annat SEO-plugin är installerat','Hreflang'=>'Hreflang','Disabled (by setting)'=>'Inaktiverad (genom inställning)','✓ LF outputs — plugin hreflang suppressed'=>'✓ LF-utdata — plugin hreflang undertryckt','✓ LF outputs'=>'✓ LF-utdata','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF ger exakt hreflang för varje konfigurerat språk, inklusive x-default. Generella SEO-plugins har inte tillgång till din LF-routingkonfiguration och skulle generera hreflang baserat på felaktiga URL-antaganden. LF undertrycker deras output via filter för att förhindra kollisioner.','Suppressed: %s.'=>'Undertryckt: %s.','Open Graph'=>'Open Graph','Disabled (mode setting)'=>'Inaktiverad (lägesinställning)','→ Locale tags only — deferring base OG to plugin'=>'→ Endast språkmärkningar — avstår från att använda bas-OG i pluginet','→ Locale tags only (manual setting)'=>'→ Endast språkmärkningar (manuell inställning)','✓ LF outputs full OG + Twitter Cards'=>'✓ LF-utdata full OG + Twitter Cards','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF lägger alltid till og:locale och og:locale:alternate — de flerspråkiga OG-signaler som inget allmänt SEO-plugin kan producera korrekt. För det grundläggande OG-setet (og:title, og:description, og:image), genererar LF det när inget annat plugin är närvarande. När ett SEO-plugin är installerat, hoppar LF över det grundläggande setet för att undvika duplicerade taggar — inte för att pluginet är "bättre", utan för att duplicering inte ger något värde.','Schema.org JSON-LD'=>'Schema.org JSON-LD','— Deferred to plugin'=>'— Skjutet på plugin','✓ LF outputs Article / WebPage / WebSite'=>'✓ LF-utdata Artikel / WebPage / WebSite','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF genererar flerspråkig JSON-LD med inLanguage-annoteringar kopplade till dess språkrouterning. När en SEO-plugin är installerad, inaktiverar LF helt sin egen schema: duplicerade JSON-LD-grafer ger valideringsfel och det finns inget enkelt sätt att komplettera en befintlig graf.','XML Sitemap'=>'XML-sitemap','✓ Active at /lf-sitemap.xml'=>'✓ Aktiv vid /lf-sitemap.xml','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF genererar sin egen sitemap med xhtml:link-alternativ för alla översättningsgrupper. När ett SEO-plugin är installerat, genererar det en separat sitemap — båda samexisterar oberoende. Skicka båda till Google Search Console: SEO-pluginets sitemap för innehållsupptäckt, LF:s sitemap för språkrelationer.','Canonical tag'=>'Canonical-tagg','✓ WP canonical replaced (self-referencing)'=>'✓ WP kanonisk ersatt (självrefererande)','WP core canonical active (hreflang disabled)'=>'WP-kärnens kanoniska aktiv (hreflang inaktiverat)','LF removes the WordPress core canonical tag and replaces it with a self-referencing canonical pointing to the correct language-prefixed URL. When a third-party SEO plugin (Yoast, Rank Math, AIOSEO, SEOPress) is active, LF defers canonical management to that plugin entirely.'=>'LF tar bort WordPress-kärnans kanoniska tagg och ersätter den med en självrefererande kanonisk som pekar på den rätta språkförstärkta URL:en. När ett tredjeparts SEO-plugin (Yoast, Rank Math, AIOSEO, SEOPress) är aktivt, överlåter LF kanonisk hantering helt till det pluginet.','Legacy lf-social-share mu-plugin'=>'Legacy lf-social-share mu-plugin','The lf-social-share mu-plugin is active.'=>'lf-social-share mu-plugin är aktivt.','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Lingua Forges inbyggda Social Share- och Open Graph-moduler täcker all funktionalitet som mu-plugin tillhandahåller, plus flerspråkigt og:locale-stöd. Du kan säkert inaktivera mu-pluginen.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'OG/Twitter Card-taggar: hanteras av LF:s Open Graph-modul (SEO → Open Graph & Twitter Cards)','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Sociala ikoner blockdelning: URL:er: hanteras av LF:s inbyggda Social Share (SEO → Social Share)','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'kopiera/native/auto JS-åtgärder: hanteras av LF:s social-share.js','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Medan den är aktiv, hanterar mu-plugin:en den grundläggande OG-inställningen och LF genererar endast lokalitetstaggar (autoläge). Att ta bort den växlar LF till full OG-läge automatiskt.','Debug Files'=>'Felsökningsfiler','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'När felsökningsloggning är aktiverad (via växeln nedan eller genom att definiera LINGUAFORGE_AI_DEBUG i wp-config.php) skriver översättnings- och FSE-mallöversättningsfunktionerna sina råa AI-uppmaningar och svar till disk för felsökning. Använd detta avsnitt för att övervaka den utskriften och rensa den när du har det du behöver — filerna kan växa snabbt på stora sidor. Konfigurera målmappen via filtreringen linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Felsökningsfiler rensade. %d fil togs bort.' . "\0" . 'Felsökningsfiler rensade. %d filer togs bort.','Debug logging enabled.'=>'Felsökningsloggning aktiverad.','Debug logging disabled.'=>'Felsökningsloggning inaktiverad.','Debug logging'=>'Felsökningsloggning','Write AI prompts and responses to disk for troubleshooting'=>'Skriv AI-uppmaningar och svar till disk för felsökning','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Tvingad PÅ av konstanten LINGUAFORGE_AI_DEBUG i wp-config.php. Ta bort den raden för att kontrollera växeln härifrån.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Tvingad AV av konstanten LINGUAFORGE_AI_DEBUG i wp-config.php. Ta bort den raden för att kontrollera växeln härifrån.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Filer hamnar i nedanstående katalog. Användbart för att diagnostisera översättningsproblem — stäng av när du har det du behöver så att filerna inte samlas. Du kan också tvinga detta från wp-config.php med `define( \'LINGUAFORGE_AI_DEBUG\', true );` vilket överskrider växeln.','Currently:'=>'För närvarande:','✓ Enabled'=>'✓ Aktiverad','✗ Disabled'=>'✗ Inaktiverad','Directory'=>'Katalog','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtrera med linguaforge_debug_dir för att omdirigera felsökningsutdata till en icke-offentlig plats.','Files'=>'Filer','.txt file(s) in the directory'=>'.txt-fil(er) i katalogen','Save Debug Setting'=>'Spara felsökningsinställning','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Radera alla .txt-filer i felsökningskatalogen? Katalogen själv kommer att förbli så att framtida felsökningsskrivningar fortfarande hamnar rätt.','Clear Debug Files'=>'Rensa felsökningsfiler','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge genererar <link rel="alternate" hreflang> taggar för varje konfigurerat språk på varje sida, inklusive x-default som pekar på källspråket. Detta är den primära flerspråkiga SEO-signalen för Google och andra sökmotorer — inget ytterligare SEO-plugin krävs.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'När Yoast SEO, Rank Math, All in One SEO eller SEOPress är aktivt, undertrycker Lingua Forge automatiskt deras hreflang-utdata via filter. Allmänna SEO-plugins genererar hreflang baserat på en enkel- språk-URL-struktur och kan inte ta hänsyn till din flerspråkiga routing-konfiguration; LF:s utdata är alltid korrekt.','Hreflang settings saved.'=>'Hreflang-inställningar sparade.','Hreflang output'=>'Hreflang-utdata','Output hreflang tags in wp_head'=>'Generera hreflang-taggar i wp_head','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Inaktivera endast för headless-sajter eller helt anpassade hreflang-implementeringar. När det är inaktiverat tar inte LF längre bort WordPress kärncanonical-taggen och undertrycker inte längre SEO-pluginers hreflang-utdata.','Current status'=>'Aktuellt status','✓ Hreflang active'=>'✓ Hreflang aktivt','LF is outputting hreflang tags and is replacing the WordPress core canonical with a self-referencing canonical for each language version.'=>'LF matar ut hreflang-taggar och ersätter WordPress-kärnans canonical med en självreferenserande canonical för varje språkversion.','LF is suppressing hreflang output from: %s'=>'LF undertrycker hreflang-utdata från: %s','Save Hreflang Settings'=>'Spara Hreflang-inställningar','Language Overrides'=>'Språköverskridanden','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Ladda upp kompilerade .mo-filer för att åsidosätta strängar från tredjepartsplugin för specifika språk — till exempel en anpassad VikBooking-översättning som använder "lägenhet" istället för "rum". Filer måste följa WordPress-namnkonventionen: {textdomain}-{locale}.mo (t.ex. vikbooking-ca.mo). De lagras i uppladdningsmappen och överlever plugin-uppdateringar.','Override file uploaded successfully.'=>'Åsidosättningsfil uppladdad framgångsrikt.','Override file deleted.'=>'Åsidosättningsfil raderad.','No file was selected.'=>'Ingen fil valdes.','Only .mo files are accepted.'=>'Endast .mo-filer accepteras.','The upload failed — please try again.'=>'Uppladdningen misslyckades — försök igen.','Could not save the file. Check that the uploads folder is writable.'=>'Kunde inte spara filen. Kontrollera att uppladdningsmappen är skrivbar.','Invalid filename.'=>'Ogiltigt filnamn.','Security check failed — file path is not permitted.'=>'Säkerhetskontroll misslyckades — filvägen är inte tillåten.','An unknown error occurred.'=>'Ett okänt fel inträffade.','Text domain / locale'=>'Textdomän / språk','Size'=>'Storlek','Delete all files for this override (both .mo and .po)?'=>'Ta bort alla filer för denna åsidosättning (både .mo och .po)?','Delete'=>'Ta bort','No override files uploaded yet.'=>'Inga åsidosättningsfiler har laddats upp än.','Upload .mo file'=>'Ladda upp .mo-fil','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Accepterar endast kompilerade .mo-filer. Filnamnet måste följa mönstret {textdomain}-{locale}.mo. Att ladda upp en fil med samma namn som en befintlig kommer att ersätta den.','Upload Override'=>'Ladda upp åsidosättning','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiera till säkert lagringsutrymme','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate lagrar sina anpassade översättningar i wp-content/languages/loco/ — en plats som kan raderas tyst av en WP-kärnuppdatering, plugin-ominstallation eller om Loco Translate tas bort. Att kopiera filer hit flyttar dem till Lingua Forge i18n-overrides-katalogen, som består genom alla dessa händelser och laddas automatiskt vid varje förfrågan.','File copied to safe storage successfully.'=>'Fil kopierad till säkert lagringsutrymme framgångsrikt.','Source file not found.'=>'Källfilen hittades inte.','Could not copy the file. Check that the uploads folder is writable.'=>'Kunde inte kopiera filen. Kontrollera att uppladdningsmappen är skrivbar.','Invalid file reference.'=>'Ogiltig filreferens.','Type'=>'Typ','✓ In safe storage'=>'✓ I säkert lagringsutrymme','Copy to safe storage'=>'Kopiera till säkert lagringsutrymme','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Inga anpassade Loco Translate-filer har hittats än. De visas här när du sparar en översättning i Loco Translate.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge genererar Open Graph- och Twitter Card-meta-taggar så att delade URL:er visar rätt språk, titel, beskrivning och bild på sociala plattformar.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'Till skillnad från hreflang — där LF alltid överskrider andra plugins eftersom de inte kan känna till din flerspråkiga konfiguration — är Open Graph annorlunda: Yoast, Rank Math och liknande plugins genererar redan korrekta OG-taggar för ditt innehåll. Att duplicera dem ger inget värde. I autoläge upptäcker LF aktiva SEO-plugins och lägger till endast det de inte kan tillhandahålla: og:locale (nuvarande språk) och og:locale:alternate (alla andra konfigurerade språk).','Open Graph settings saved.'=>'Open Graph-inställningar sparade.','Open Graph output'=>'Open Graph-utgång','Output Open Graph tags in wp_head'=>'Generera Open Graph-taggar i wp_head','Output mode'=>'Utskriftsläge','Auto (recommended)'=>'Auto (rekommenderas)','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Upptäck aktiva SEO-plugins (Yoast, Rank Math, etc.) vid körning. Sänd endast og:locale + og:locale:alternate när en annan plugin redan genererar hela OG-setet; sänd hela setet när ingen detekteras.','Locale only'=>'Endast lokal','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Alltid endast utgå från og:locale och og:locale:alternate. Används när ett annat plugin eller tema hanterar hela OG-setet.','Full'=>'Fullständig','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Alltid utgå från hela OG + Twitter Card-setet oavsett andra plugins. Används endast om inget annat plugin genererar OG-taggar.','Disabled'=>'Inaktiverad','Do not output any OG tags.'=>'Generera inga OG-taggar.','Default OG image'=>'Standard OG-bild','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Fallback-bild-URL som används när en sida inte har någon utvald bild, webbplatslogotyp eller webbplatsikon. Visas i sociala förhandsvisningar för arkiv, bloggens index och vilken som helst enskild sida utan miniatyrbild.','— Disabled'=>'— Inaktiverad','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktiv — språkmärkningar endast (og:locale, og:locale:alternate)','✓ Active — full OG + Twitter Cards'=>'✓ Aktiv — full OG + Twitter Cards','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Legacy lf-social-share mu-plugin upptäckt. LF skjuter upp den grundläggande OG-setet till mu-pluginet och genererar endast og:locale + og:locale:alternate. Du kan inaktivera mu-pluginet — LF:s inbyggda Social Share (SEO → Social Share-fliken) och Open Graph täcker samma funktionalitet.','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'SEO-plugin(er) upptäckta: %s. LF visar endast og:locale och og:locale:alternate; det upptäckta pluginet hanterar hela OG-setet.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Inget externt OG-plugin upptäckt. LF genererar hela OG + Twitter Card-setet.','Save Open Graph Settings'=>'Spara Open Graph-inställningar','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge genererar Schema.org JSON-LD-strukturerad data så att sökmotorer förstår din innehållstyp, språk och metadata. Detta är det primära sättet att kommunicera inLanguage-annoteringar för flerspråkigt innehåll till Google och andra crawlers.','Schema output deferred.'=>'Schema-utmatning fördröjd.','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s är aktiv och genererar redan Schema.org JSON-LD. Lingua Forge har inaktiverat sin egen schemautmatning för att förhindra konflikter. Till skillnad från Open Graph — där LF lägger till og:locale ovanpå ett annat plugins utdata — kan schema inte enkelt kompletteras: duplicerade eller överlappande JSON-LD grafer ger valideringsfel. Inaktivera schemautmatningen i den upptäckta pluginen om du vill att LF ska hantera strukturerad data.','Schema.org settings saved.'=>'Schema.org-inställningar sparade.','Schema.org output'=>'Schema.org-utmatning','Output Schema.org JSON-LD in wp_head'=>'Output Schema.org JSON-LD i wp_head','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Låst — en konfliktande SEO-plugin är aktiv. Se meddelandet ovan.','Article / WebPage'=>'Artikel / Webbsida','Output Article or WebPage schema on singular posts and pages'=>'Generera Article eller WebPage-schema på enskilda inlägg och sidor','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Blogginlägg använder Artikel; alla andra inläggstyper och sidor använder Webbsida. Inkluderar rubrik, beskrivning, inLanguage, url, publiceringsdatum, ändringsdatum, bild och utgivare.','WebSite'=>'Webbplats','Output WebSite schema on the front page and blog index'=>'Visa WebSite-schema på förstasidan och bloggens index','Includes site name, url, and inLanguage.'=>'Inkluderar webbplatsnamn, url och inLanguage.','Product'=>'Produkt','Output Product schema on WooCommerce product pages'=>'Generera Product-schema på WooCommerce-produkt sidor','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Inkluderar namn, beskrivning, inLanguage, url, bild och ett erbjudande med pris, valutat och tillgänglighet. Pris och tillgänglighet kommer från källspråkets produkt (delat lager).','Currently emitting'=>'För närvarande sänds','Article / WebPage — all singular posts and pages'=>'Artikel / Webbsida — alla enskilda inlägg och sidor','WebSite — front page / blog index'=>'Webbplats — startsida / bloggindex','Product — WooCommerce product pages'=>'Produkt — WooCommerce-produkt sidor','Nothing — all types disabled'=>'Inget — alla typer inaktiverade','Save Schema.org Settings'=>'Spara Schema.org-inställningar','Blog / Editorial'=>'Blogg / Redaktionellt','Product / eCommerce'=>'Produkt / E-handel','Landing / Short-form'=>'Landningssida / Kortformat','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtrera efter språk och inläggstyp, bläddra i ditt innehåll, och klicka på Analysera på valfritt objekt för att köra en regelbaserad SEO-granskning — titelns längd, meta-beskrivning, ordantal, rubbningstruktur, bild-ALT-coverage och interna länkar.','Treat H2 as H1 equivalent'=>'Behandla H2 som H1-ersättning','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Aktivera när ditt tema renderar inläggets titel som en H2 istället för en H1 (vanligt i vissa block-teman). Analysatorn hämtar den renderade sidan och, om den inte hittar någon H1 men hittar en H2, höjer den första H2 till H1 för poängsättning.','Save analysis settings'=>'Spara analysinställningar','Per-Post Analysis'=>'Per-inläggsanalys','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Välj ett inlägg och kör en detaljerad SEO-granskning för att se resultat per-mått och ett betyg för det specifika objektet.','Language'=>'Språk','source'=>'källa','All types'=>'Alla typer','Load content'=>'Ladda innehåll','Batch Analysis'=>'Batchanalys','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Kör en fullständig SEO-granskning över alla publicerade inlägg för ett eller alla aktiva språk. Poäng sparas per inlägg och återspeglas i språkkolumnens märken i inläggslistan.','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'WooCommerce-systemssidor (butik, kundvagn, kassa, mitt konto) är exkluderade — deras innehåll hanteras av WooCommerce och kan inte förbättras genom SEO-redigeringar.','Post type'=>'Inläggstyp','Default profile'=>'Standardprofil','— Auto-detect —'=>'— Upptäck automatiskt —','Analyse all languages'=>'Analysera alla språk','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Auto-detektering tilldelar: WooCommerce-produkter → Produktprofil; den statiska startsidan → Landningsprofil; allt annat → Bloggprofil. Välj en specifik profil för att åsidosätta detta för alla inlägg.','%d post'=>'%d inlägg' . "\0" . '%d inlägg','Last run: %s ago'=>'Senaste körning: %s sedan','Never run'=>'Aldrig kör','avg'=>'genomsnitt','(partial)'=>'(delvis)','Analyse'=>'Analysera','(no title) #%d'=>'(ingen titel) #%d','Invalid post ID.'=>'Ogiltigt inläggs-ID.','Post not found or not published.'=>'Inlägget hittades inte eller publicerades inte.','~%d min read'=>'~%d min läsning' . "\0" . '~%d min läsning','No title set.'=>'Inget titel satt.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Titeln är %1$d tecken — kan trunkeras i SERPs (sikta på under %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Titeln är bara %d tecken — sikta på minst 10 tecken.','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Enkelords titel (%d tecken) — att lägga till ett andra ord förbättrar tydlighet och nyckelordsomfång.','%1$d chars, %2$d words — good title.'=>'%1$d tecken, %2$d ord — bra titel.','Using LF AI meta description.'=>'Använder LF AI meta-beskrivning.','No LF meta description set — using excerpt/content.'=>'Ingen LF-meta-beskrivning satt — använder utdrag/innehåll.','No meta description found. Generate one via the AI meta description feature.'=>'Ingen meta-beskrivning hittades. Generera en via AI-meta-beskrivningsfunktionen.','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d tecken — för kort (sikta på %2$d–%3$d). %4$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d tecken — troligen avklippta i SERPs (håll dig under %2$d). %3$s','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d tecken — bra, något över den ideala %2$d men inom det accepterade %3$d-teckensintervallet. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d tecken — ideal längd. %2$s','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d ord — mycket tunt innehål. Överväg att utöka till minst %2$d ord.','%1$d words — below recommended minimum of %2$d.'=>'%1$d ord — under rekommenderat minimum på %2$d.','%d words.'=>'%d ord.','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'H2-som-H1-läge aktiverat — titeln räknas som H1-ersättning. (Rubriktaggar kunde inte upptäckas från den renderade sidan; verifiera att ditt tema visar titeln korrekt.)','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Inga H1 hittades. Vanligtvis är inläggets titel H1 — verifiera att ditt tema genererar den.','%d H1 tags found — a page should have exactly one H1.'=>'%d H1-taggar hittades — en sida bör ha exakt en H1.','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — ingen H2, men %d H3-underavsnitt hittades (t.ex. accordion/detaljhuvuden). Strukturen är acceptabel.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — kort innehåll (%d stycken), underrubriker inte nödvändiga.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — inga H2 underrubriker (acceptabelt för denna typ av innehåll).','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — inga H2- eller H3-underrubriker hittades. Att lägga till H2:or förbättrar strukturen.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','No images found in content.'=>'Inga bilder hittades i innehållet.','%1$d of %2$d image(s) missing alt text.'=>'%1$d av %2$d bilder saknar alt-text.','%d image(s), all have alt text.'=>'%d bild(er), alla har alt-text.','No links found. Internal links improve crawlability and user navigation.'=>'Inga länkar hittades. Interna länkar förbättrar genomsökbarhet och användarnavigation.','No links found.'=>'Inga länkar hittades.','%d external link(s), no internal links. Add internal links to related content.'=>'%d externt länk(e), inga interna länkar. Lägg till interna länkar till relaterat innehåll.','%d external link(s), no internal links.'=>'%d extern länk(er), inga interna länkar.','%1$d internal, %2$d external.'=>'%1$d internt, %2$d externt.','Post not found.'=>'Inlägget hittades inte.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Ingen AI-leverantör konfigurerad. Lägg till en API-nyckel i Inställningar → API-nycklar.','No response from AI provider. Check your API key and try again.'=>'Inget svar från AI-leverantör. Kontrollera din API-nyckel och försök igen.','AI returned an unexpected response format. Please try again.'=>'AI returnerade ett oväntat svar. Försök igen.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge genererar en dedikerad XML-sitemap på /lf-sitemap.xml som lägger till språk-Alternativ länkar för allt ditt översatta innehåll. Denna sitemap kompletterar WordPress kärnsitemap och eventuella SEO-plugin-sitemaps — den ersätter dem inte.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'WordPress-kärnens sitemap listar alla dina innehålls-URL:er. LF-sitemapen berättar för sökmotorer hur språkversioner förhåller sig till varandra via xhtml:link hreflang-varianten. Skicka båda till Google Search Console för full täckning.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s är aktiv och genererar sin egen sitemap. Den sitemap är separat från LF:s. Båda bör skickas till Google Search Console: SEO-pluginets sitemap listar ditt innehåll; LF:s sitemap lägger till de flerspråkiga alternativen. LF:s sitemap meddelas automatiskt i robots.txt.','Sitemap settings saved.'=>'Sitemap-inställningar sparade.','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Sitemap-cache rensad. Den kommer att genereras om på nästa besök till sitemap-URL:en.','Sitemap output'=>'Sitemap-utmatning','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Generera den flerspråkiga sitemapen vid /lf-sitemap.xml','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'När aktiverat, annonseras sitemap-URL:en automatiskt i robots.txt och cachen uppdateras när översatt innehåll sparas.','Sitemap URL'=>'Sitemap-URL','Submit this URL to Google Search Console alongside your main sitemap.'=>'Skicka denna URL till Google Search Console tillsammans med din huvudsitemap.','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Inte ännu genererad. Sitemappen byggs vid första besöket till sitemap-URL:en och cachas i 24 timmar.','✓ Active — %d URL entry with language alternates'=>'✓ Aktiv — %d URL-Post med språkvarianter' . "\0" . '✓ Aktiv — %d URL-poster med språkvarianter','No translated content found. The sitemap will populate once posts have been translated.'=>'Ingen översatt innehåll hittades. Sitemappen kommer att fyllas på när inlägg har översatts.','Last generated: %s'=>'Senast genererad: %s','Save Sitemap Settings'=>'Spara Sitemap-inställningar','Flush Sitemap Cache'=>'Töm sitemap-cache','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Tvingar sitemap att regenereras vid nästa förfrågan. Används efter bulkimport eller manuell redigering av översättningsrelationer.','IndexNow'=>'IndexNow','IndexNow is an open protocol supported by Bing, Yandex, and other search engines. When a translated post is published or updated, Lingua Forge automatically notifies all participating engines in a single push — no polling, no waiting for the next robots.txt crawl.'=>'IndexNow är ett öppet protokoll som stöds av Bing, Yandex och andra sökmotorer. När ett översatt inlägg publiceras eller uppdateras, meddelar Lingua Forge automatiskt alla deltagande motorer i ett enda push — ingen polling, ingen väntan på nästa robots.txt-sökning.','IndexNow replaces the deprecated Bing and Yandex sitemap-ping endpoints. Google discovers sitemaps via the robots.txt Sitemap: directive as before.'=>'IndexNow ersätter de föråldrade Bing- och Yandex-sitemap-ping-endpoints. Google upptäcker sitemaps via robots.txt Sitemap: direktivet som tidigare.','✓ All URLs submitted to IndexNow successfully.'=>'✓ Alla URL:er som skickats till IndexNow lyckades.','No translated URLs found to submit. Publish some translated posts first.'=>'Inga översatta URL:er att skicka in hittades. Publicera några översatta inlägg först.','✗ IndexNow submission failed. Check that the key file is publicly reachable (see below) and try again.'=>'✗ IndexNow-inlämning misslyckades. Kontrollera att nyckelfilen är offentligt tillgänglig (se nedan) och försök igen.','Verification key'=>'Verifikationsnyckel','Key file served automatically at: %s'=>'Nyckelfil levereras automatiskt på: %s','Key could not be generated. Check that the site has write access to WordPress options.'=>'Nyckeln kunde inte genereras. Kontrollera att webbplatsen har skrivåtkomst till WordPress-alternativen.','Key file status'=>'Nyckelfilens status','✓ Key file is publicly reachable.'=>'✓ Nyckelfilen är offentligt tillgänglig.','✗ Key file is not reachable.'=>'✗ Nyckelfilen är inte tillgänglig.','IndexNow engines verify the key file before accepting submissions. If the file is not reachable, submissions will be rejected with a 403 error.'=>'IndexNow-motorer verifierar nyckelfilen innan de accepterar inskick. Om filen inte är tillgänglig, kommer inskick att avvisas med ett 403-fel.','Common causes: full-page caching (clear it), a security plugin blocking .txt files, or a custom Nginx/Apache rule. The file is served by LF on every request — no physical file is written to disk.'=>'Vanliga orsaker: fullsidcaching (rensa den), ett säkerhetsplugin som blockerar .txt-filer, eller en anpassad Nginx/Apache-regel. Filen levereras av LF vid varje förfrågan — ingen fysisk fil skrivs till disk.','Submit all URLs'=>'Skicka in alla webbadresser','Submit all URLs via IndexNow'=>'Skicka alla URL:er via IndexNow','Pushes every published, LF-managed URL to IndexNow in one batch. Automatic submission already runs on every publish/update — use this only after a bulk import or when setting up IndexNow for the first time.'=>'Pushar varje publicerad, LF-hanterad URL till IndexNow i en batch. Automatisk inlämning körs redan vid varje publicering/uppdatering — använd detta endast efter en bulkimport eller när du sätter upp IndexNow för första gången.','Google does not participate in IndexNow. It discovers sitemaps via the robots.txt Sitemap: directive — which LF has already configured. Use Google Search Console to monitor indexing coverage.'=>'Google deltar inte i IndexNow. Det upptäcker webbplatskartor via direktivet Sitemap: i robots.txt — som LF redan har konfigurerat. Använd Google Search Console för att övervaka indexeringstäckningen.','Open Search Console →'=>'Öppna Search Console →','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt uppdaterad med Sitemap-direktiv.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Fysisk robots.txt hittad. LF:s Sitemap-direktiv är närvarande.','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Ett fysiskt robots.txt-fil finns i webbplatsens rot. WordPress virtuella robots.txt — och LF:s Sitemap: filter — kringgås. LF:s sitemap meddelas inte till sökmotorer.','Add Sitemap directive to robots.txt'=>'Lägg till Sitemap-direktivet i robots.txt','Appends the following line to your existing robots.txt: %s'=>'Lägger till följande rad till din befintliga robots.txt: %s','DISALLOW_FILE_MODS is set.'=>'DISALLOW_FILE_MODS är satt.','Add the following line to your robots.txt manually:'=>'Lägg till följande rad i din robots.txt manuellt:','View current robots.txt'=>'Visa aktuell robots.txt','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Ingen fysisk robots.txt-fil hittades. WordPress genererar den virtuellt och LF:s Sitemap-direktiv är inkluderat automatiskt.','The following directive is active in your virtual robots.txt:'=>'Följande riktlinje är aktiv i din virtuella robots.txt:','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Filändringar är inaktiverade (DISALLOW_FILE_MODS).','Could not write to robots.txt. Check file permissions.'=>'Kunde inte skriva till robots.txt. Kontrollera filbehörigheterna.','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge utökar WordPress Core Social Icons-blocket med dynamiska delnings-URL:er. Sätt vilken ikon som helst länk till ett "share:"-värde och LF skriver om det till rätt delnings-URL eller JavaScript-åtgärd vid rendering — ingen anpassad kod eller tredjepartsplugin krävs.','Social Share settings saved.'=>'Sociala delningsinställningar sparade.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'lf-social-share mu-plugin är aktivt. Lingua Forges inbyggda sociala delning är inaktiv — mu-plugin hanterar delnings-URL-omskrivning och JS-åtgärder.','Social Share'=>'Social Share','Enable Social Share URL rewriting for Social Icons blocks'=>'Aktivera social delnings-URL-omskrivning för sociala ikonsblock','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Inaktiverad eftersom lf-social-share mu-plugin redan tillhandahåller denna funktion.','Save Social Share Settings'=>'Spara Social Share-inställningar','How to use'=>'Hur man använder','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'I blockredigeraren, lägg till ett Social Icons-block. För varje ikon, öppna länkinställningarna och ange ett av "share:"-värdena nedan som URL. På frontend ersätter LF det med rätt delnings-URL för den aktuella sidan.','External share services'=>'Externa delningstjänster','URL to enter'=>'URL att ange','Action'=>'Åtgärd','Share on Facebook'=>'Dela på Facebook','Post on X / Twitter'=>'Inlägg på X / Twitter','Share on LinkedIn'=>'Dela på LinkedIn','Send via WhatsApp'=>'Skicka via WhatsApp','Send via Telegram'=>'Skicka via Telegram','Submit to Reddit'=>'Skicka till Reddit','Pin on Pinterest'=>'Pinna på Pinterest','Share on Mastodon'=>'Dela på Mastodon','Share via email (mailto:)'=>'Dela via e-post (mailto:)','JavaScript-powered actions'=>'JavaScript-drivna åtgärder','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Kopiera den aktuella URL:en till urklipp. Visar en "Länk kopierad"-toast vid framgång.','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Öppna webbläsarens inbyggda Web Share-blad (iOS, Android, vissa skrivbord). Fall tillbaka till kopiering till clipboard om inte stöds.','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Använd inbyggd delning när det är tillgängligt; fall tillbaka till att kopiera till klippbordet. Rekommenderad standard för "Dela"-knappar.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'Delnings-URL:en speglar alltid den aktuella sidan — ingen manuell URL-inmatning krävs. filteret linguaforge_social_share_url låter dig åsidosätta den lösta URL:en för vilken tjänst som helst.','Configuration issue: WP site language has no content on this site'=>'Konfigurationsproblem: Webbplatsens språk har inget innehål på denna webbplats','The WordPress site language (%1$s) maps to the language code "%2$s", but no posts on this site are tagged _lf_lang=%2$s. This causes WooCommerce product queries to return zero results, product images to fail, and all language-filtered content queries to break.'=>'WordPress-webbplatsens språk (%1$s) mappas till språkkoden "%2$s", men inga inlägg på denna webbplats är märkta med _lf_lang=%2$s. Detta gör att WooCommerce-produktfrågor returnerar noll resultat, produktbilder misslyckas och alla språkfiltrerade innehållsfrågor bryts.','Fix: go to'=>'Fixa: gå till','Settings → General → Site Language'=>'Inställningar → Allmänt → Webbplatsens språk','and set it to one of your actual content languages (e.g. %s).'=>'och ställ in den på ett av dina faktiska innehållsspråk (t.ex. %s).','Environment'=>'Miljö','Lingua Forge version'=>'Lingua Forge-version','WordPress version'=>'WordPress-version','PHP version'=>'PHP-version','Active theme'=>'Aktivt tema','(FSE / block theme)'=>'(FSE / blocktema)','(classic theme)'=>'(klassiskt tema)','URL structure'=>'URL-struktur','Subdomain (de.example.com)'=>'Subdomän (de.example.com)','Path prefix (/de/)'=>'Sökvägsprefix (/de/)','WP instance language'=>'WP-instansens språk','not a content language — see notice above'=>'inte ett innehållsspråk — se meddelande ovan','Primary content language'=>'Primärt innehållsspråk','Active languages'=>'Aktiva språk','PHP max_execution_time'=>'PHP max_execution_time','No PHP limit'=>'Inget PHP-begränsning','(server/FPM timeout still applies)'=>'(server/FPM timeout gäller fortfarande)','AI translation and batch analysis may time out. Recommend 120s or more.'=>'AI-översättning och batchanalys kan ta timeout. Rekommenderas 120 sek eller mer.','PHP memory_limit'=>'PHP memory_limit','AI Configuration'=>'AI-konfiguration','(active)'=>'(aktiv)','Configured'=>'Konfigurerad','No key'=>'Ingen nyckel','— AI features are disabled.'=>'— AI-funktioner är inaktiverade.','Add key →'=>'Lägg till nyckel →','Light model'=>'Lätt modell','Quality model'=>'Kvalitetsmodell','Active preset'=>'Aktivt preset','Daily quota'=>'Daglig kvot','Unlimited'=>'Obegränsad','requests / day'=>'förfrågningar / dag','Permalink Structure'=>'Permalänksstruktur','Permalink structure is compatible with Lingua Forge path routing.'=>'Permalänksstrukturen är kompatibel med Lingua Forges sökvägsrouting.','Plain permalinks are not supported.'=>'Enkla permalänkar stöds inte.','Path routing requires a post-name based permalink structure. Change it in'=>'Sökvägsrouting kräver en permalänkstruktur baserad på inläggsnamn. Ändra det i','Settings → Permalinks'=>'Inställningar → Permalänkar','Numeric permalink structure is not supported.'=>'Numerisk permalänkstruktur stöds inte.','Switch to a post-name based structure in'=>'Byt till en struktur baserad på inläggsnamn i','SEO Plugins'=>'SEO-plugins','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Inga tredjeparts-SEO-plugins upptäckta. Lingua Forge hanterar all flerspråkig SEO-utdata.','Active: %s.'=>'Aktivt: %s.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Se Inställningar → SEO → Kompatibilitet för hela tabellen över beteende per funktion.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce är inte aktivt.','Shop'=>'Butik','Cart'=>'Varukorg','Checkout'=>'Kassan','My Account'=>'Mitt konto','WooCommerce version'=>'WooCommerce-version','Order storage'=>'Orderlagring','High-Performance Order Storage (HPOS)'=>'Högpresterande orderlagring (HPOS)','Custom tables — LF post-meta filters do not affect orders.'=>'Anpassade tabeller — LF post-meta-filter påverkar inte beställningar.','Shared / compatibility mode'=>'Delad / kompatibilitetsläge','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT synkroniserad — övergångsperiod; LF post-meta-filter gäller för CPT-kopia.','Legacy post-based (CPT)'=>'Legacy-inläggsbaserad (CPT)','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Order i wp_posts — se till att shop_order är utesluten från LF-routing.','WcPageBridge active'=>'WcPageBridge aktiv','Yes'=>'Ja','No — WooCommerce integration class not loaded'=>'Ingen — WooCommerce-integration klass inte laddad','WooCommerce page translations'=>'WooCommerce-sidöversättningar','No secondary languages configured.'=>'Inga sekundära språk konfigurerade.','Active Plugins'=>'Aktiva plugins','No active plugins detected.'=>'Inga aktiva plugins upptäckta.','Version'=>'Version','_lf_lang Coverage'=>'_lf_lang täckning','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Inlägg utan _lf_lang är osynliga för varje Lingua Forge-språkfilter. Detta kan hända när innehåll importeras eller skapas innan pluginet aktiverades.','All published posts have a _lf_lang value. No gaps detected.'=>'Alla publicerade inlägg har ett _lf_lang-värde. Inga luckor upptäckta.','Missing'=>'Saknas','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Exkludera denna inläggstyp från språkrouting — dess inlägg kommer inte längre att visas här eller få _lf_lang. Detta kan inte ångras automatiskt.','Exclude from routing'=>'Exkludera från routing','excluded from routing'=>'exkluderad från routing','Destructive action — read before proceeding'=>'Förstörande åtgärd — läs innan du fortsätter','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Reparera taggar för varje routbar post listad ovan med _lf_lang = %s. Poster i routing-utexkluderade posttyper påverkas inte. Kör detta endast efter import av innehåll eller vid initial aktivering — använd inte som ett massivt språk-omfördelningsverktyg.','Repair — assign _lf_lang = %s to all routable posts above'=>'Reparera — tilldela _lf_lang = %s till alla routbara poster ovan','Rewrite Rules'=>'Omkopplingsregler','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'LF-ägda poster som för närvarande är registrerade i $wp_rewrite->extra_rules_top. Användbara för att diagnostisera 404 eller routingkonflikter. Kopiera dessa när du rapporterar ett fel.','%d rule registered'=>'%d registrerade regler' . "\0" . '%d registrerade regler','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Inga LF-omskrivningsregler hittades. Rensa permalänkar om detta är oväntat.','Debug Info'=>'Felsökningsinformation','Copy and paste into a GitHub issue or support request.'=>'Kopiera och klistra in i ett GitHub-ärende eller supportbegäran.','Copy system info'=>'Kopiera systeminformation','Copied!'=>'Kopierad!','Repairing…'=>'Reparerar…','Repair failed.'=>'Reparation misslyckades.','Network error.'=>'Nätverksfel.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Exkludera denna inläggstyp från språkrouting? Dess inlägg kommer inte längre att visas i denna lista eller få _lf_lang. Du kan ångra detta i Inställningar → Router → Query Filter Exclusions.','Excluding…'=>'Exkluderar…','Failed to save exclusion.'=>'Misslyckades med att spara exkludering.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d inlägg märkta med _lf_lang = %2$s.' . "\0" . '%1$d inlägg märkta med _lf_lang = %2$s.','Uninstall Behaviour'=>'Avinstallera Beteende','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Styr vad som händer när en administratör tar bort pluginet från Plugins → Installerade Plugins → Ta bort. Plugin-inställningar och AI-cache raderas alltid. Språkuppdrag och översättningsrelationer behålls som standard så att en oavsiktlig avinstallation eller ominstallation kan fortsätta där den slutade.','Uninstall setting saved.'=>'Avinstallationsinställning sparad.','Delete content data on uninstall'=>'Radera innehållsdata vid avinstallation','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Radera också språkuppdrag, översättningsrelationer, metabeskrivningar, ordlista och översättningstextminne när pluginet avinstalleras','Warning:'=>'Varning:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Om markerad kommer avinstallationen av pluginet att permanent radera alla språkuppdrag, översättningsrelationer, metabeskrivningar, sidbaserade förinställningar, AI-ordlistan och översättningstextminnet för varje inlägg på denna webbplats. Detta kan inte ångras. Lämna omarkerat om du helt tar bort flerspråkstöd från webbplatsen.','Save Uninstall Setting'=>'Spara avinstallationsinställning','Today'=>'Idag','Last 7 days'=>'Senaste 7 dagarna','Last 30 days'=>'Senaste 30 dagarna','All time'=>'Alltid','AI Usage'=>'AI-användning','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Tokenförbrukning summerad per funktion, leverantör och modell. Registreras vid varje lyckad AI-anrop; testanslutningspings är exkluderade så att de inte snedvrider totalsumman.','Check your account, billing, or remaining credits directly on the provider console:'=>'Kontrollera ditt konto, fakturering eller återstående krediter direkt på leverantörens kontrollpanel:','Anthropic Console'=>'Anthropic Console','OpenAI Platform'=>'OpenAI-plattform','Google AI Studio'=>'Google AI Studio','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Inga AI-användningar har registrerats än. När en redigerare gör en översättning, genererar en meta-beskrivning eller använder någon annan AI-funktion, visas totalsummorna här.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Inga AI-användningar registrerade i det valda fönstret (%s). Välj ett bredare intervall ovan.','Provider'=>'Leverantör','Model'=>'Modell','Requests'=>'Förfrågningar','Input tokens'=>'Inmatningstokens','Output tokens'=>'Utgångstokens','Total tokens'=>'Totalt tokens','Total'=>'Totalt','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge lägger till WooCommerce-specifika Open Graph-egenskaper till produktsidor så att delning av en produkt-URL på Facebook, Pinterest och liknande plattformar visar rätt produkttyp, pris och tillgänglighet.','WooCommerce SEO settings saved.'=>'WooCommerce SEO-inställningar sparade.','Product Open Graph'=>'Produkt Open Graph','Add WooCommerce product tags to Open Graph output'=>'Lägg till WooCommerce-produkt-taggar till Open Graph-utmatningen','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'När aktiverat, genererar Lingua Forge följande ytterligare meta-taggar på produktsidor: og:type=product, og:price:amount, og:price:currency, og:availability, och deras product: namespace-ersättningar som används av Facebook Catalog.','Tags emitted'=>'Taggar sänds ut','Tag'=>'Tagg','Value source'=>'Värdekälla','"product" (replaces "article")'=>'"produkt" (ersätter "artikel")','WooCommerce product price'=>'WooCommerce-produktpris','WooCommerce store currency'=>'WooCommerce-butikens valuta','instock / oos / pending from WC stock status'=>'i lager / slut på lager / väntande från WC-lagertillstånd','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Pris och tillgänglighet speglar alltid produkten på källspråket (delat lager). Taggar visas endast när LF:s Open Graph-modul är inställd på "Full" eller "Auto" läge utan konfliktande SEO-plugin.','Save WooCommerce SEO Settings'=>'Spara WooCommerce SEO-inställningar','AI Provider'=>'AI-leverantör','AI Usage & Cache'=>'AI-användning & cache','API Keys'=>'API-nycklar','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Nycklar krypteras med AES-256-CBC innan de lagras i WordPress-databasen. Krypteringshemligheten hämtas från dina WordPress-autentiseringssalter (wp-config.php), så klartextnycklar berör aldrig databasen.','API credentials are managed by WordPress in %s. No key is stored by Lingua Forge.'=>'API-uppgifter hanteras av WordPress i %s. Ingen nyckel lagras av Lingua Forge.','Settings → Connectors'=>'Inställningar → Anslutningar','API Key'=>'API-nyckel','Paste your API key…'=>'Klistra in din API-nyckel…','✓ Configured'=>'✓ Konfigurerad','✗ Not configured'=>'✗ Inte konfigurerad','Test connection'=>'Testa anslutning','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Lämna tomt för att behålla den befintliga nyckeln. Ange ett nytt värde för att ersätta den.','Remove stored key'=>'Ta bort lagrad nyckel','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Denna nyckel tillhandahålls för närvarande av en server %s och kan inte tas bort här. Ange en ny nyckel ovan för att åsidosätta den med ett databasvärde.','environment variable'=>'miljövariabel','PHP constant'=>'PHP-konstant','Alternative (server-side):'=>'Alternativ (serverside):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Du kan också definiera nycklar som konstanter eller miljövariabler (t.ex. i wp-config.php). Dessa källor används automatiskt som fallback när ingen databasnyckel är lagrad.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'För att använda en anpassad krypteringshemlighet (istället för det härledda wp_salt-värdet), lägg till detta i wp-config.php:','Unknown provider.'=>'Okänd leverantör.','No API key configured for this provider.'=>'Ingen API-nyckel konfigurerad för denna leverantör.','Could not instantiate the provider.'=>'Kunde inte instansiera leverantören.','Provider returned no response. Check the WordPress error log for details.'=>'Leverantören gav inget svar. Kontrollera WordPress-felloggen för detaljer.','Enter a model identifier to test.'=>'Ange en modellidentifierare för att testa.','No published post or page found to test with — publish some content first, or try Quick Translate directly.'=>'Inget publicerat inlägg eller sida hittades för testning – publicera något innehål först, eller prova Snabböversättning direkt.','(untitled)'=>'(ingen titel)','Prompt template not found.'=>'Prompt-mall hittades inte.','Translation failed. Please try again.'=>'Översättningen misslyckades. Försök igen.','The sample post has no visible text content to translate.'=>'Exempelinlägget har inget synligt textinnehål att översätta.','Chunk prompt template not found.'=>'Chunk-prompt-mall hittades inte.','Model returned no response. Check the WordPress error log for details.'=>'Modellen returnerade inget svar. Kontrollera WordPress-felloggen för detaljer.','Behavior'=>'Beteende','Block Editor'=>'Blockredigerare','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge begränsar två Gutenberg-funktioner som standard för att hålla redaktionellt beteende konsekvent över språk. Välj här om du behöver fulla Gutenberg / FSE-funktioner.','Block locking'=>'Blocklåsning','Allow editors to lock individual blocks'=>'Tillåt redaktörer att låsa enskilda block','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Återaktiverar Gutenbergs canLockBlocks. Användbart för redaktionella mallar som behöver förhindra att bidragsgivare flyttar eller raderar specifika block.','Template mode'=>'Mallläge','Allow Gutenberg template-editing mode on post screens'=>'Tillåt Gutenberg-mallredigeringsläge på inläggssidor','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Återaktiverar supportsTemplateMode. Kärnan i Full-Site-Editing-arbetsflöden där mallöverskridanden på inläggsnivå är avsiktliga.','Compliance Preset'=>'Efterlevnadsförinställning','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Strikt bevarandestil för juridiskt, reglerande, medicinskt eller tekniskt innehåll. När den är aktiverad använder varje AI-funktion en låg samplingstemperatur och lägger till tillägget nedan till dess systemprompt — terminologi, artikelnummer, enheter, varumärken och reglerande språk bevaras exakt snarare än att omformuleras.','Global AI preset'=>'Global AI-förinställning','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0,2–0,6, per funktion','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Sätter den förvalda AI-beteendet för hela webbplatsen. Enskilda inlägg kan åsidosätta detta för Översättning och Innehållsgenerering via Lingua Forge-meta-rutan.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard använder varje funktions egen justerade temperatur: Översättning T=0,2 (precis), Snabb översättning T=0,4, Innehållsgenerator T=0,6 (kreativ). De andra förinställningarna tillämpar en enda fast temperatur över alla funktioner.','Technical / Scientific instructions'=>'Tekniska / Vetenskapliga instruktioner','Legal / Compliance instructions'=>'Juridiska / Efterlevnadsinstruktioner','Creative / Marketing instructions'=>'Kreativa / Marknadsföringsinstruktioner','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Lämna tomt för att använda den inbyggda standarden. Radera en sparad överskridande inställning för att återställa standarden vid nästa spara.','View built-in default'=>'Visa inbyggd standard','Automatic Translation Backfill'=>'Automatisk backup för översättning','Periodically scans for posts missing a translation in an active language and queues an AI translation for each gap found — the same recovery you can already trigger by hand via "Translate missing" or the WP-CLI missing_translations/fill_translations commands, run automatically once an hour instead.'=>'Skannar regelbundet efter inlägg som saknar en översättning på ett aktivt språk och köar en AI-översättning för varje gap som hittas – samma återställning som du redan kan utlösa manuellt via "Översätt saknade" eller WP-CLI-kommandona missing_translations/fill_translations, körd automatiskt en gång i timmen istället.','Automatic backfill'=>'Automatisk backup','Automatically translate posts missing a language version'=>'Översätt automatiskt inlägg som saknar en språkversion','Off by default. This feature makes AI provider requests — and spends the associated API cost — automatically and in the background, with no per-request confirmation, for every published post found without a translation in an active language. Turn this on only if you want every content gap translated unattended; otherwise use "Translate missing" or the WP-CLI commands to translate on your own schedule.'=>'Inaktiverad som standard. Den här funktionen gör AI-leverantörförfrågningar – och spenderar den associerade API-kostnaden – automatiskt och i bakgrunden, utan bekräftelse per begäran, för varje publicerat inlägg utan översättning på ett aktivt språk. Aktivera detta endast om du vill att varje innehållsgap ska översättas utan övervakning; använd annars "Översätt saknade" eller WP-CLI-kommandona för att översätta enligt ditt eget schema.','WooCommerce products and variations are never included, regardless of this setting. An integration can also block specific post types via the linguaforge_cpt_create_allowed filter.'=>'WooCommerce-produkter och varianter ingår aldrig, oavsett denna inställning. En integration kan också blockera specifika inläggstyper via filtret linguaforge_cpt_create_allowed.','The "Sync" button in the post list Lang column retranslates a post out into every other language, including the primary/source post when it\'s run from a translation. That back-translation direction is restricted by default for every post type. (WooCommerce products and variations have their own separate setting below — this one does not affect them.)'=>'Knappen "Synkronisera" i kolumnen Lang på inlägglistan översätter ett inlägg till varje annat språk, inklusive det primära/källspråket när det körs från en översättning. Den backtranslation-riktningen är begränsad som standard för varje inläggstyp. (WooCommerce-produkter och varianter har sin egen separata inställning nedan – denna påverkar dem inte.)','Secondary-language Sync'=>'Sekundärspråkig synkronisering','Allow "Sync" on a translated post to overwrite the primary post'=>'Tillåt "Synkronisera" på ett översatt inlägg att skriva över det primära inlägget','Off by default: clicking "Sync" on a translation is blocked from overwriting the primary post. Syncing FROM the primary post to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Inaktiverad som standard: att klicka på "Synkronisera" på en översättning blockeras från att skriva över det primära inlägget. Synkronisering FRÅN det primära inlägget till varje översättning är alltid tillåten oavsett denna inställning. Aktivera detta endast om du avsiktligt vill att en översättning ska kunna bli det nya källinnehållet.','The primary-language product is WooCommerce\'s operational source of truth for price, SKU, and stock, which are always served from it regardless of which language a shopper is viewing. This is a separate, independent setting from the general "Sync" restriction above — enabling one does not enable the other.'=>'Den primärspråkiga produkten är WooCommerce:s operationella sanningskälla för pris, SKU och lager, som alltid serveras från den oavsett vilket språk en köpare visar. Det här är en separat, oberoende inställning från den allmänna "Synkronisering"-begränsningen ovan – att aktivera den ena aktiverar inte den andra.','Allow "Sync" on a translated product to overwrite the primary product'=>'Tillåt "Synkronisera" på en översatt produkt att skriva över den primära produkten','Off by default: clicking "Sync" on a translated WooCommerce product is blocked, since it would back-translate onto the primary product\'s title, description, and excerpt. Syncing FROM the primary product to every translation is always allowed regardless of this setting. Turn this on only if you intentionally want a translation to be able to become the new source content.'=>'Inaktiverad som standard: att klicka på "Synkronisera" på en översatt WooCommerce-produkt blockeras, eftersom det skulle backtranslate på den primära produktens titel, beskrivning och utdrag. Synkronisering FRÅN den primära produkten till varje översättning är alltid tillåten oavsett denna inställning. Aktivera detta endast om du avsiktligt vill att en översättning ska kunna bli det nya källinnehållet.','General'=>'Allmänt','Light'=>'Ljus','Meta Description, Excerpt Generator, quick translate'=>'Meta-beskrivning, utdraggenerator, snabb översättning','Quality'=>'Kvalitet','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Helt sidöversättning, Innehållsgenerator (mellantypmodeller är fullt tillräckliga)','Active Provider'=>'Aktiv leverantör','Currently inherited from the %s constant. Selecting a value here will override it.'=>'För närvarande ärvs från konstanten %s. Att välja ett värde här kommer att åsidosätta det.','WordPress AI Client — requirements:'=>'WordPress AI-klient — krav:','Full-page translation uses JSON-schema-constrained output. This requires a connector plugin to be installed and active (not just an API key saved in Settings → Connectors). If translation fails, check the PHP error log for the specific error, or switch to a built-in provider.'=>'Fullsidetranslation använder JSON-schema-begränsad output. Detta kräver att en connector-plugin är installerad och aktiv (inte bara en API-nyckel sparad i Inställningar → Connectors). Om översättningen misslyckas, kontrollera PHP-felloggen för det specifika felet, eller byt till en inbyggd provider.','Manage your account, review usage, or top up credits:'=>'Hantera ditt konto, granska användning eller fyll på krediter:','WordPress Connectors'=>'WordPress-kopplingar','Models'=>'Modeller','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funktioner är grupperade i två nivåer. Ange den exakta modellidentifieraren för varje nivå och leverantör. Lämna ett fält tomt för att använda den inbyggda standarden (visas som platshållare). Endast den aktiva leverantörens modeller anropas vid körning — konfigurera de andra i förväg om du planerar att byta.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Börja skriva i något fält för att se modellförslag, eller använd referenstabellen nedan. Lätta och mellankvalitetsmodeller (Haiku, GPT-4o mini, Gemini Flash) är fullt tillräckliga för översättning och innehållsgenerering — flaggskepps "max"-modeller tillför kostnad med minimal kvalitetsökning för strukturerat text.','active'=>'aktiv','Model selection is managed by WordPress in %s — no model identifier is stored by Lingua Forge for this provider.'=>'Modellval hanteras av WordPress i %s — ingen modellidentifierare lagras av Lingua Forge för denna provider.','overridden'=>'åtsidosatt','Translates a short sample of your most recent published post with this exact model — a real, billed API call.'=>'Översätter ett kort urval av ditt senaste publicerade inlägg med denna exakta modell – ett verkligt, debiterat API-anrop.','Test model'=>'Testmodell','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tips: för att återställa en modell till den inbyggda standarden, rensa fältet och spara.','Available models reference'=>'Referens för tillgängliga modeller','Model ID'=>'Modell-ID','Name'=>'Namn','Tier'=>'Nivå','Notes'=>'Anteckningar','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Detta katalog uppdateras med varje Lingua Forge-utgåva. Testa en anslutning i fliken API-nycklar hämtar också den live-modelllistan från leverantören och uppdaterar förslagen ovan.','Glossary'=>'Ordlista','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Användarhanterad terminologitabell per språkpar. Poster läggs till i översättningssystemets prompt så att AI:n använder föredragna termer konsekvent — avgörande för domänvokabulär ("kWp", "PPA", "interconnection point"), varumärken som inte får översättas, och standardiserad regleringsformulering. Båda språkfälten är valfria: lämna "Källspråk" tomt för att tillämpa posten oavsett vilket språk du översätter från; lämna "Mål språk" tomt för att tillämpa den på alla mål språk samtidigt.','Glossary entry added.'=>'Glossaripost tillagd.','Glossary entry removed.'=>'Glossaripost borttagen.','Could not add entry: source term and target term are required.'=>'Kunde inte lägga till post: källterm och målterm krävs.','Could not save the glossary entry.'=>'Kunde inte spara glossariposten.','Source language'=>'Källspråk','— Any —'=>'— Valfritt —','Target language'=>'Målspråk','— Any target —'=>'— Alla mål —','Filter'=>'Filtrera','Reset'=>'Återställ','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Inga glossariposter matchar det aktuella filtret. Rensa filtret för att se alla poster, eller lägg till en ny post nedan.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Inga glossariposter än. Lägg till en nedan för att börja tillämpa terminologi i översättningarna.','Source term'=>'Källterm','Target term'=>'Målterm','Source lang'=>'Källa språk','Target lang'=>'Mål språk','any'=>'valfritt','Delete this glossary entry?'=>'Vill du ta bort denna glossaripost?','Add new entry'=>'Lägg till ny post','The phrase as it appears in the source text.'=>'Frasen som den förekommer i källtexten.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Hur den ska visas i översättningen. Skriv samma värde som källtermen för att instruera AI:n att behålla den exakt.','— Any source language —'=>'— Valfritt källspråk —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Lämna tomt för varumärken och språkoberoende termer som ska tillämpas oavsett vilket språk vi översätter från.','— Any target language —'=>'— Valfritt målspråk —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Lämna tomt för att tillämpa denna post på alla målspråk — idealiskt för varumärken, förkortningar och termer som måste behållas exakt i varje översättning.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Valfri kontext för redaktörer (t.ex. "ASIC = Application-Specific Integrated Circuit; behåll på engelska i tekniska sammanhang").','Add entry'=>'Lägg till post','Limits'=>'Gränser','Authors and above (edit_published_posts)'=>'Författare och högre (edit_published_posts)','Contributors and above — default (edit_posts)'=>'Bidragsgivare och högre — standard (edit_posts)','Editors and above (edit_others_posts)'=>'Redaktörer och högre (edit_others_posts)','Administrators only (manage_options)'=>'Endast administratörer (manage_options)','AI Limits & Security'=>'AI-gränser & säkerhet','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Begränsa hur mycket AI-användning webbplatsen kan generera och begränsa vilka användarroller som kan utlösa betalda AI-anrop. Sitter ovanpå den per-användare takgräns (30 förfrågningar / minut, hårdkodat) som redan skyddar mot enskilda användare som springer iväg.','Daily request limit'=>'Dagligt förfrågningsgräns','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Webbplatsövergripande tak för AI-förfrågningar per UTC-dag (räknar både Verktygsfältets översättningar och blockrevisioner). Räknaren återställs vid UTC-midnatt. Sätt till 0 för att inaktivera taket.','Minimum role'=>'Minsta roll','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Lägsta WordPress-kompetens som tillåts utlösa AI-funktioner. Att begränsa detta på flerskaparesajter förhindrar Bidragsgivare eller testkonton från att köra betalda AI-anrop. Överstyr per funktion via filteret linguaforge_required_capability.','Translation Limits'=>'Översättningsgränser','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontrollera hur mycket innehåll som skickas till AI och hur stort svaret kan vara. Lämna ett fält tomt för att använda den inbyggda standarden (visas som platshållare). Höj dessa värden om stora sidor klipps av; sänk dem för att minska API-kostnader.','Model tier'=>'Modellnivå','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kvalitet (standard — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Ljus (snabbt och kostnadseffektivt — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Vilken modellnivå som ska användas för helsidetranslation. Kvalitet använder modellen konfigurerad i tabellen Modeller ovan och rekommenderas för noggrann, långformig översättning. Byt till Ljus endast om hastighet eller kostnad är prioriterat och innehållet är kort.','Max output tokens'=>'Max utdata tokens','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maximalt antal tokens som AI kan producera i ett enda översättningssvar. Om en översättning tyst klipps av i slutet, öka detta värde. Standard: 16 000.','Max input characters'=>'Max inmatningskaraktärer','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maximalt antal tecken för inläggets innehåll som vidarebefordras till AI. 0 betyder ingen gräns — hela innehållet skickas alltid (rekommenderas). Sätt ett icke-nollvärde endast om din leverantör har ett snävt sammanhangsfönster. En varning skrivs till PHP-felloggen när innehållet klipps.','Quick Translation'=>'Snabb översättning','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Snabb översättning används för snipp- eller chunk-läge — korta passager översätts på begäran från verktygsfältet, redigeraren eller blockets popovers. Det använder en separat, lättare konfiguration än helsidetranslation för att hålla svaren snabba och kostnadseffektiva.','Light (default — fast and cost-effective)'=>'Lätt (standard — snabbt och kostnadseffektivt)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kvalitet (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Lättnivån använder den snabba modellen som konfigurerats i tabellen Modeller ovan (standard: Haiku / Flash). Byt till Kvalitet om du behöver samma översättningsnoggrannhet som i helsidläge för snippar.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maximalt antal tokens som AI kan producera per snabb översättning. Standard: 2 000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maximalt antal tecken som accepteras från inmatningsfältet. Standard: 8 000.','Content Generator'=>'Innehållsgenerator','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Styr tokenbudget och inmatningsgränser för AI Content Generator-funktionen. Lämna fälten tomma för att använda de inbyggda standardvärdena.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maximalt antal tokens som AI kan producera per genereringskörning. Öka detta om hela artiklar klipps av. Standard: 8 192.','Max hints characters'=>'Max antal hints-tecken','Maximum characters read from the Hints field. Default: 2 000.'=>'Maximalt antal tecken som läses från hints-fältet. Standard: 2 000.','Max context characters'=>'Maximalt sammanhangstecken','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maximalt antal tecken av befintligt inläggs innehåll som skickas till AI som frö-sammanhang när inga hints ges. Standard: 6 000.','Maintenance'=>'Underhåll','Router'=>'Router','Primary language saved.'=>'Primärt språk sparat.','Permalink rules flushed successfully.'=>'Permalänkrensning lyckades.','Language uninstalled. %d post deleted.'=>'Språk avinstallerat. %d inlägg raderade.' . "\0" . 'Språk avinstallerat. %d inlägg raderade.','%d locale file removed.'=>'%d lokalfil borttagen.' . "\0" . '%d lokalfiler borttagna.','%d pattern translation removed.'=>'%d mönsteröversättning borttagen.' . "\0" . '%d mönsteröversättningar borttagna.','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'%d lokalfil kunde inte tas bort automatiskt (DISALLOW_FILE_MODS är aktiverat). Ta bort den manuellt via din server eller WP-CLI: wp language core uninstall <locale>.' . "\0" . '%d lokalfiler kunde inte tas bort automatiskt (DISALLOW_FILE_MODS är aktiverat). Ta bort dem manuellt via din server eller WP-CLI: wp language core uninstall <locale>.','Primary Language'=>'Primärt språk','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Det primära språket tjänas alltid på rotad av din webbplats — ingen URL-prefix i sökvägsmode, ingen språksubdomän i subdomänläge. Alla andra språk använder antingen en /lang/ sökvägsprefix (t.ex. example.com/de/) eller en språksubdomän (t.ex. de.example.com), beroende på URL-strukturinställningen nedan.','Primary language'=>'Primärt språk','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Efter att ha ändrat det primära språket, töm permalänkar (avsnitt nedan) för att uppdatera URL-routing.','Path prefix — example.com/de/'=>'Sökvägsprefix — example.com/se/','Subdomain — de.example.com/'=>'Subdomän — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Subdomänläge kräver att din webbserver pekar alla språksubdomäner (t.ex. de.example.com) till denna WordPress-installation. Efter att ha bytt läge, töm permalänregler och rensa eventuella cache. Om din hemsides-URL inkluderar www (t.ex. www.example.com), använd lf_base_domain-filtret för att ställa in den rena toppdomänen så att subdomäner konstrueras korrekt.','Browser language redirect'=>'Webbläsarspråk-omdirigering','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Omdirigera besökare till deras föredragna språk baserat på webbläsarens Accept-Language-header','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'När detta är aktiverat omdirigeras förstagångsbesökare utan språkcookie och utan språkprefix i URL:en till den närmaste matchande språkversionen. Omdirigeringen hoppas över om webbläsarens föredragna språk inte är bland de aktiva router-språken. När en besökare väljer ett språk via switchern, prioriteras cookien och webbläsarens header ignoreras vid framtida besök.','Query Filter Exclusions'=>'Query Filter Exclusions','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge begränsar sekundära WP_Query-instansier (sidwidgetar, mallblock, plugin-sökningar) till den aktiva språket genom att injicera ett _lf_lang meta-begränsning. Inläggstyper som listas här är undantagna från den begränsningen — deras frågor är alltid ofiltrerade.','Contact Form 7 (wpcf7_contact_form), Flamingo contacts and inbound messages (flamingo_contact, flamingo_inbound), and WordPress language-pack sync storage (wp_sync_storage) are excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Contact Form 7 (wpcf7_contact_form), Flamingo-kontakter och inkommande meddelanden (flamingo_contact, flamingo_inbound), samt WordPress språkpaket-synk lagring (wp_sync_storage) är automatiskt undantagna. Lägg till andra tredjartypers inlägg som inte ska språkfiltreras, en per rad eller kommaseparerat.','Excluded post types'=>'Exkluderade inläggstyper','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Posttyp-sluggar separerade med kommatecken eller nya rader. Ändringar träder i kraft omedelbart vid spara — ingen permalänk-flush krävs.','WooCommerce Integration'=>'WooCommerce-integrering','Controls how Lingua Forge integrates with WooCommerce order processing.'=>'Styr hur Lingua Forge integreras med WooCommerce-orderhantering.','Order line item source mapping'=>'Orderradssökning för kartläggning','Normalize order line item product IDs to the source-language product at checkout'=>'Normalisera orderradsprodukt-ID till källspråkets produkt vid kassan','When enabled (recommended), the product ID stored on each WooCommerce order line item is set to the source-language product. This ensures total_sales counts, WC Analytics revenue rows, and third-party ERP exports reference one product ID per SKU rather than one per language version. Trade-off: "View product" links in order emails and My Account lead to the source-language page. Disable only if a connected system relies on translated product IDs in orders. Use the linguaforge_wc_order_item_source_mapping filter for per-item overrides.'=>'När det är aktiverat (rekommenderas) sätts produkt-ID:t som lagras på varje WooCommerce-orderrad till källspråkets produkt. Detta säkerställer att total_sales-räkningar, WC Analytics intäktsrader och tredjeparts ERP-exporter refererar till ett produkt-ID per SKU snarare än en per språkversion. Nackdel: "Visa produkt"-länkar i ordermail och Mitt konto leder till källspråkssidan. Inaktivera endast om ett anslutet system förlitar sig på översatta produkt-ID:n i beställningar. Använd filtert linguaforge_wc_order_item_source_mapping för per-objekt-överskridanden.','Save Router Settings'=>'Spara routerinställningar','Flush Permalinks'=>'Töm permalänkar','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regenererar WordPress-omskrivningsregler så URL-prefix, språkspecifika slugs och arkivomskrivningar är i synk. Nödvändigt efter att ha ändrat primärt språk eller lagt till nytt språkstöd.','Flush Permalink Rules'=>'Töm permalänkriktlinjer','Active Languages'=>'Aktiva språk','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Språk som för närvarande är kända för routern (hämtade från installerade WordPress-lokalpaket plus det primära språket). Installera ytterligare språkpaket i avsnittet nedan för att göra fler språk tillgängliga för routing och översättning.','%d locale pack installed.'=>'%d lokalpaket installerat.' . "\0" . '%d lokalpaket installerade.','Install a Language'=>'Installera ett språk','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Ladda ner och installera ett WordPress-kärnspråkpaket direkt från WordPress.org. När det är installerat blir språket tillgängligt för URL-routing och AI-översättningsarbetsflödet. Listan över tillgängliga språk hämtas vid behov — klicka på knappen nedan för att ladda den.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Språkinstallation är inaktiverad på denna server. Konstanten DISALLOW_FILE_MODS är inställd i wp-config.php. Installera språkpaket manuellt via WP-CLI: wp language core install de_DE','Load available languages'=>'Ladda tillgängliga språk','— select a language —'=>'— välj ett språk —','Install'=>'Installera','Language Setup'=>'Språksetup','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Inga sekundära språk konfigurerade. Installera ett språkpaket ovan för att aktivera mallstrukturering.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Välj ett språk för att hantera dess FSE-mallar, malldelar och navigationsmenyer.','Recreate All Languages'=>'Återskapa alla språk','Recreate All Languages (Templates Only)'=>'Återskapa alla språk (endast mallar)','Recreate All Languages (Template Parts Only)'=>'Återskapa alla språk (endast malldelar)','Cancel'=>'Avbryt','Repair Template Metadata'=>'Reparera mallmetadata','Fixes the Site Editor namespace and _lf_lang tag on all LF-scaffolded FSE templates stored in the database. Run this once after updating from an earlier version of Lingua Forge — it moves WooCommerce-derived templates from the active-theme group to the WooCommerce group in the Site Editor, and ensures all scaffolded templates are discoverable by coverage reports.'=>'Fixar Site Editor-namespace och _lf_lang-taggen på alla LF-ramverkade FSE-mallar som lagras i databasen. Kör detta en gång efter att ha uppdaterat från en tidigare version av Lingua Forge — det flyttar WooCommerce-deriverade mallar från aktiv-tema-gruppen till WooCommerce-gruppen i Site Editor, och säkerställer att alla ramverkade mallar är upptäckbara av täckningsrapporter.','Repair template metadata'=>'Reparera mallmetadata','Request failed.'=>'Begäran misslyckades.','Forbidden'=>'Förbjuden','Danger Zone'=>'Farlig zon','Uninstall %s'=>'Avinstallera %s','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Raderar permanent alla mallar, malldelar, mönster, navigationsmenyer, inlägg, sidor, anpassade inläggstyper, produkter och produktvarianter kopplade till detta språk. Tar också bort WordPress lokalpaketfiler så att detta språk inte längre visas i routern. Denna åtgärd kan inte ångras.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Detta språk matchar WordPress-instansens lokal och kan inte avinstalleras.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Avinstallerar du %s permanent? Detta kommer att radera allt översatt innehåll för detta språk och kan inte ångras.','Invalid language code.'=>'Ogiltig språkkod.','This language is protected and cannot be uninstalled.'=>'Detta språk är skyddat och kan inte avinstalleras.','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Språkinstallation är inaktiverad på denna server (DISALLOW_FILE_MODS är inställt).','Invalid locale code.'=>'Ogiltig lokal kod.','Language %s installed successfully.'=>'Språket %s installerades framgångsrikt.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Installation av språkpaket misslyckades. Språket kan redan vara installerat, lokal-koden kan vara felaktig, eller så kan din server blockera filskrivningar.','Navigations'=>'Navigationer','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Navigation översättning kräver en aktiv AI-leverantör. Konfigurera en API-nyckel i fliken API-nycklar.','Navigation'=>'Navigation','Re-translate'=>'Oversätt igen','CPT Block Patterns'=>'CPT Blockmönster','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Blockmönster registrerade för anpassade inläggstyper. Använd knappen Översätt för att skapa en språkvariant. Det översatta innehållet sparas här och kan kopieras till vilket CPT-inlägg som helst från blockredigerarens mönsterinserter eller användas som utgångspunkt för ett Synkroniserat mönster (Återanvänt block).','Pattern'=>'Mönster','Post Types'=>'Inläggstyper','✓ Translation saved'=>'✓ Översättning sparad','View'=>'Visa','Template Parts'=>'Malldelar','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Språk-specifika kopior av temats malldelar. När de är scaffoldade, uppdateras mallarna för att referera till den språk-specifika delen.','Re-create all'=>'Återskapa alla','Translate all'=>'Översätt allt','Fix all links'=>'Fixa alla länkar','Fix all navs'=>'Fixa alla navigeringar','Part'=>'Del','Status / Actions'=>'Status / Åtgärder','Create'=>'Skapa','Templates'=>'Mallar','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'FSE-mallar sådda från det aktiva temat. Skapa och anpassa i webbplatsredigeraren.','Create missing'=>'Skapa saknade','Fix all parts'=>'Fixa alla delar','SEO'=>'SEO','Multilingual SEO'=>'Flerspråkig SEO','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Konfigurera hreflang, Open Graph, Schema.org, webbplatskartor och social delning för varje språk på din webbplats. Varje avsnitt nedan hanterar ett aspekt av flerspråkig SEO.','Open Graph &amp; Twitter Cards'=>'Open Graph & Twitter Cards','Schema.org'=>'Schema.org','Sitemap'=>'Sitemap','Analysis'=>'Analys','Compatibility'=>'Kompatibilitet','System'=>'System','Overview'=>'Översikt','Lingua Forge Settings'=>'Lingua Forge-inställningar','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge lägger till flerspråkig routing, AI-driven översättning, hreflang SEO-taggar och en språkväxlare till din WordPress-webbplats.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Använd flikarna högst upp på den här sidan för att konfigurera varje område. Ändringar i fliken Router träder i kraft omedelbart; ändringar i AI-nycklar och modellinställningar gäller för nästa AI-förfrågan.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Efter att ha ändrat URL-strukturinställningarna (sökvägs-prefix ↔ subdomän), besök alltid Inställningar → Permalänkar och klicka på Spara ändringar för att rensa omskrivningsreglerna.','AI Provider Tab'=>'AI-leverantör Flik','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Select the active provider from the dropdown — only one provider is used at a time. Enter an API key for that provider to enable AI features.'=>'Stödda leverantörer: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Välj den aktiva leverantören från rullgardinsmenyn — endast en leverantör används åt gången. Ange en API-nyckel för den leverantören för att aktivera AI-funktioner.','Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Nycklar är krypterade i vila med AES-256-GCM med en webbplatsspecifik hemlighet (LINGUAFORGE_SECRET). Dela inte databasexporter utan att först rotera hemligheten.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI-funktioner är valfria. Språkstyrning, hreflang, språkväxlaren och översättningsgruppssystemet fungerar alla utan att en leverantör är konfigurerad.','Model tiers'=>'Modellnivåer','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge använder två modellnivåer per leverantör:','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Ljus: används för meta-beskrivningar och utdragsskapande — snabbt, låga kostnader.','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kvalitet: används för inläggsöversättning och innehållsgenerering — högre kvalitet, högre kostnad.','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Lämna ett modellfält tomt för att använda den inbyggda standarden för den nivån. Platsinnehållet visar vilken modell som kommer att användas.','Translation Limits & Behavior'=>'Begränsningar och beteende för översättning','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Begränsningar för översättning: styr vilka användarroller som kan utlösa AI-översättning, och sätt en månatlig tokenbudget. Att överskrida budgeten avbryter AI-anrop tills månaden är slut.','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Beteende: välj AI-förinställning (Literal, Balanced, Creative), lägg till anpassade instruktioner för hela webbplatsen, aktivera eller inaktivera automatisk översättning efter inläggssparning, och konfigurera översättningsminnet.','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Översättningsminne cache:ar AI-resultat efter innehållshash, språkpar, leverantör och modell. Att redigera ett inlägg ogiltigförklarar cache-inträdet så att nästa översättningsanrop får ett nytt resultat.','Router Tab'=>'Router-flik','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Primärt språk: det språk ditt befintliga innehåll är skrivet på. Alla översättningar produceras från detta språk; att ändra det flyttar eller raderar inte några inlägg.','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL-struktur: path-prefix-läge (example.com/de/) kräver inga serverändringar. Subdomänläge (de.example.com) kräver en wildcard-DNS-post, ett wildcard-SSL-certifikat och en konfigurationsändring av webbservern — se guiden för serverinställningar.','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktiva språk: lägg till varje språk du vill stödja. Varje språk får en URL-prefix eller subdomän och en hreflang-tagg i sidans &lt;head&gt;.','WP site language requirement'=>'Krav på WP-webbplatsens språk','The WordPress site language (Settings → General → Site Language) must be set to one of the languages you use for content — either the primary content language or one of the secondary languages. It cannot be a language that has no content on the site.'=>'Språk för WordPress-webbplatsen (Inställningar → Allmänt → Webbplatsens språk) måste vara inställt på ett av de språk du använder för innehåll — antingen det primära innehållsspråket eller ett av de sekundära språken. Det kan inte vara ett språk som inte har något innehåll på webbplatsen.','Example of a supported configuration: WP site language = CA (Catalan), content languages = CA + ES.'=>'Exempel på en stödd konfiguration: WP-webbplatsens språk = CA (Katalanska), innehållsspråk = CA + ES.','Example of an unsupported configuration: WP site language = EN (English), content languages = CA + ES only. English is not a content language, so Lingua Forge cannot map the WP locale to any translation group.'=>'Exempel på en icke-stödd konfiguration: WP-webbplatsens språk = EN (Engelska), innehållsspråk = CA + ES endast. Engelska är inte ett innehållsspråk, så Lingua Forge kan inte mappa WP-lokalen till någon översättningsgrupp.','When the WP site language is not a content language: WooCommerce product queries return zero results on all catalogue blocks; product image delegation fails; all language-filtered content queries break; the language switcher may show a spurious non-content language option. If you see a red configuration alert at the top of the Router or System tab, correct the site language first.'=>'När WP-webbplatsens språk inte är ett innehållsspråk: WooCommerce-produktfrågor ger noll resultat i alla katalogblock; produktbilddelegation misslyckas; alla innehållsfrågor filtrerade efter språk bryts; språkväxlaren kan visa ett falskt icke-innehållsspråkalternativ. Om du ser en röd konfigurationsvarning högst upp i Router- eller System-fliken, korrigera först webbplatsens språk.','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE-lokalisering: skapa, översätt och fixa länkar i Full Site Editing-mallar och malldelar direkt från denna flik.','Glossary Tab'=>'Ordförråd-flik','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Fäst termer som inte får översättas eller alltid måste renderas på ett specifikt sätt (t.ex. varumärken, produktnamn, akronymer). Ordförrådsbegränsningar injiceras i varje AI-översättningsbegäran för alla funktioner: inläggsöversättning, meta-beskrivning, utdrag och FSE-mallöversättning.','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Lägg till ett villkor per rad. Både källvillkoret och målöversättningen krävs. Paret för språk avgör vilka översättningsjobb som villkoret gäller för.','SEO Tab'=>'SEO-flik','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge är en komplett flerspråkig SEO-lösning. Inget ytterligare SEO-plugin eller sitemap-plugin krävs.','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Vad LF tillhandahåller: hreflang-taggar för varje konfigurerat språk, Open Graph och Twitter Card-taggar med og:locale och og:locale:alternate, Schema.org JSON-LD med inLanguage-annoteringar, och en dedikerad flerspråkig sitemap på /lf-sitemap.xml med xhtml:link-alternativ för alla översättningsgrupper.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Sitemappen annonseras automatiskt i robots.txt. Alla stora sökmotorer — Google, Bing, Yandex — upptäcker den från robots.txt. Ingen manuell inlämning krävs.','SEO plugins and conflict avoidance:'=>'SEO-plugins och konfliktundvikande:','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Om du har Yoast SEO, Rank Math, All in One SEO eller SEOPress installerat, upptäcker Lingua Forge dem och anpassar sig för att undvika duplicerad utdata. För hreflang tar LF över helt och hållet och undertrycker pluginets utdata eftersom dessa plugins inte kan producera korrekt hreflang för en flerspråkig routingskonfiguration. För Open Graph lägger LF till endast og:locale och og:locale:alternate — de flerspråkiga signalerna som pluginet inte kan tillhandahålla — och lämnar den grundläggande OG-setet till pluginet. För Schema.org inaktiverar LF sin egen utdata helt för att undvika konflikter i JSON-LD-grafen.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'SEO → Kompatibilitet-fliken visar den aktuella detekteringsstatusen och förklarar exakt vad LF gör för varje funktion.','SEO Scores'=>'SEO-poäng','SEO Score System'=>'SEO-poängsystem','Score computation'=>'Poängberäkning','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Varje inlägg poängsätts 0–100 utifrån sex regelbaserade mätvärden: titel, meta-beskrivning, ordantal, rubriksstruktur, bild-ALT-täckning och interna länkar. Tio poäng tilldelas alltid för lästid (endast information). De återstående 90 poängen fördelas över de andra mätvärdena med vikter som varierar efter innehållsprofil (se nedan).','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Varje mätvärde ger ett av fyra tillstånd: ok (full vikt), varning (50 % av vikten), misslyckande (0), eller info (0, ingen straffpoäng). En poäng ≥ 80 är grönt, 50–79 amber, under 50 rött.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Regler för poängsättning av titel (alla profiler): misslyckas om tom; varnas om färre än 10 tecken; varnas om endast ett ord; varnas om längre än profilens SERP-gräns (60 tecken för Blogg, 70 för Produkt/Landing); okej om minst 10 tecken, minst 2 ord, och inom SERP-gränsen.','Content profiles and weights'=>'Innehållsprofiler och vikter','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profiler anpassar trösklar och vikter till den typ av innehåll som analyseras. Profilen löses automatiskt; du kan åsidosätta den per analyskörning från profilsnurran.','Blog / Editorial (default)'=>'Blogg / Redaktion (standard)','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Titel 15 poäng · Meta-beskrivning 20 poäng · Ordantal 15 poäng · Rubriker 20 poäng · Bilder 10 poäng · Länkar 10 poäng. Titel SERP-gräns 60 tecken; meta 120–210 tecken; ordantal varnar under 300, misslyckas under 100; H2 krävs; interna länkar krävs.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Auto-detekterad för WooCommerce-produkter. Titel 20 poäng · Meta-beskrivning 30 poäng · Ordantal 15 poäng · Rubriker 5 poäng · Bilder 20 poäng · Länkar 0 poäng. Titel SERP-gräns 70 tecken; ordvarning under 80, misslyckas under 40; H2 och interna länkar är valfria.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Auto-detekterad för den statiska startsidan; kan väljas manuellt. Titel 20 poäng · Meta-beskrivning 30 poäng · Ordantal 15 poäng · Rubriker 10 poäng · Bilder 15 poäng · Länkar 0 poäng. Titel SERP-gräns 70 tecken; ordvarning under 150, misslyckas under 60; H2 och interna länkar är valfria.','Heading structure rules'=>'Regler för rubriksstruktur','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Exakt ett H1 krävs. H1 är normalt inläggets titel som renderas av temat — den läses från den live-renderade sidan när det är möjligt, och från inläggets innehåll som fallback.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'När bloggprofilen kräver en H2 och ingen finns, kontrollerar analysatorn först H3-underrubriker innan varning utfärdas. Accordion- och Details-blocken använder som standard H3 för sina rubriker; dessa H3:or accepteras som giltig struktur och ger ett okej-resultat, inte en varning.','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Kort innehåll (3 stycken eller färre) straffas aldrig för saknade underrubriker, oavsett profil. En koncis sida drar inte nytta av tvingad rubrikstruktur.','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Behandla H2 som H1-ekvivalent" (Inställningar → SEO → Analys): aktivera detta när ditt tema renderar inläggstiteln inuti en H2 istället för en H1. Analysatorn höjer den första H2 till H1 så att poängen inte felaktigt dras ner.','Score history and badges'=>'Poänghistorik och märken','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Varje gång ett inlägg analyseras lagras poängen i inläggets meta. Inläggslistans Språk-kolumn visar ett färgkodad "SEO N"-märke för alla inlägg som har analyserats minst en gång. När två poäng lagras visas en deltaindikator (↑N / ↓N) som visar förändringen sedan föregående körning.','AI Usage & Cache Tab'=>'AI-användning & cache-flik','Token usage'=>'Tokenanvändning','The usage table shows AI token consumption broken down by feature (translation, meta description, excerpt, FSE template, batch analysis), provider, and model. Use the date-range buttons to filter by today, last 7 days, last 30 days, or all time.'=>'Användningstabellen visar AI-tokenförbrukning uppdelad efter funktion (översättning, meta-beskrivning, utdrag, FSE-mall, batchanalys), leverantör och modell. Använd datum-intervallet för att filtrera efter idag, de senaste 7 dagarna, de senaste 30 dagarna eller all tid.','The daily quota (configured in Behavior → Limits) is tracked here. When the quota is reached, AI calls are suspended for the rest of the day. The table shows how much of the quota has been consumed.'=>'Den dagliga kvoten (konfigurerad i Beteende → Begränsningar) spåras här. När kvoten är uppnådd, avbryts AI-anrop för resten av dagen. Tabellen visar hur mycket av kvoten som har förbrukats.','Translation caching'=>'Översättningscaching','Lingua Forge uses two independent caching layers to reduce redundant AI API calls:'=>'Lingua Forge använder två oberoende cache-lager för att minska onödiga AI API-anrop:','Stores raw AI responses keyed by content hash, language pair, provider, model, and preset. Cache entries are invalidated automatically when the source post content changes. Clear individual post entries or the whole cache from this tab.'=>'Lagrar råa AI-svar nycklade efter innehållshash, språkpar, leverantör, modell och förinställning. Cacheposter ogiltigförklaras automatiskt när källinnehållet ändras. Rensa individuella inlägg eller hela cachen från denna flik.','Stores the full translated post output per content hash. Opt-in (enabled in Behavior). Speeds up repeated translations of unchanged content. Clear it here when you want to force a fresh AI pass regardless of whether the content has changed.'=>'Lagrar den fullständiga översatta inläggsoutputen per innehållshash. Opt-in (aktiverat i Beteende). Snabbar upp upprepade översättningar av oförändrat innehåll. Rensa den här när du vill tvinga en ny AI-genomgång oavsett om innehållet har ändrats.','Maintenance Tab'=>'Underhållsflik','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Språköverskridningar: hantera anpassade .po/.mo-överskrivningsfiler för Lingua Forge UI-strängar. Använd detta istället för att redigera plugin-filer direkt — överskrivningar överlever uppdateringar.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Felsök: aktivera felsökningsloggen för att fånga AI-uppmaningar och API-svar till en lokal fil. Inaktivera efter felsökning — felsökningsläget skriver en fil vid varje AI-förfrågan.','Uninstall Behaviour: controls what is deleted when the plugin is removed from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments, translation relationships, meta descriptions, glossary, and Translation Memory are kept by default so an accidental uninstall or reinstall can pick up where it left off. Enable "Delete content data on uninstall" only when you are fully removing multilingual support from the site — this cannot be undone.'=>'Beteende vid avinstallation: styr vad som raderas när pluginet tas bort från Plugins → Installerade plugins → Ta bort. Plugininställningar och AI-cache raderas alltid. Språk tilldelningar, översättningsrelationer, meta-beskrivningar, ordlista och Översättningsminne behålls som standard så att en oavsiktlig avinstallation eller ominstallation kan fortsätta där den slutade. Aktivera "Radera innehållsdata vid avinstallation" endast när du helt tar bort flerspråkstöd från webbplatsen — detta kan inte ångras.','System Tab'=>'Systemflik','Read-only diagnostics for the current installation. No settings are changed here — use it to verify configuration, spot problems, and gather information for bug reports.'=>'Läs-Only diagnostik för den aktuella installationen. Inga inställningar ändras här — använd det för att verifiera konfiguration, upptäcka problem och samla information för felrapporter.','Sections'=>'Avsnitt','Lingua Forge, WordPress, and PHP versions; active theme; URL structure; WP site language and primary content language. A red indicator next to the WP site language means it is not one of the active content languages — fix it in Settings → General before anything else.'=>'Lingua Forge, WordPress och PHP-versioner; aktivt tema; URL-struktur; WP-webbplatsens språk och primärt innehållsspråk. En röd indikator bredvid WP-webbplatsens språk betyder att det inte är ett av de aktiva innehållsspråken — åtgärda detta i Inställningar → Allmänt innan något annat.','Active provider, configured keys, model tier selections, preset, and daily quota.'=>'Aktiv leverantör, konfigurerade nycklar, modellnivåval, förinställning och daglig kvot.','Confirms the permalink structure is compatible with Lingua Forge path routing. Plain and numeric-only structures are not supported.'=>'Bekräftar att permalänkstrukturen är kompatibel med Lingua Forge vägruttning. Enkla och numeriska strukturer stöds inte.','Lists any active third-party SEO plugins. Lingua Forge adapts its output when these are present — see Settings → SEO → Compatibility for the per-feature breakdown.'=>'Lista över aktiva tredjarts SEO-plugins. Lingua Forge anpassar sitt utdata när dessa finns — se Inställningar → SEO → Kompatibilitet för fördelning per funktion.','WooCommerce version, order storage mode (CPT / HPOS / shared), and a per-language translation coverage table for the four built-in WC pages (Shop, Cart, Checkout, My Account).'=>'WooCommerce-version, lagringsläge för beställningar (CPT / HPOS / delad) och en tabell för översättningsomfång per språk för de fyra inbyggda WC-sidorna (Shop, Cart, Checkout, My Account).','Lists post types that have published posts without a _lf_lang meta value. Posts missing this tag are invisible to all language filters. Use the Repair button to tag them with the source language, or Exclude to remove the post type from language routing entirely.'=>'Lista inläggstyper som har publicerade inlägg utan _lf_lang-metavärde. Inlägg som saknar denna tagg är osynliga för alla språkfilter. Använd Reparera-knappen för att märka dem med källspråket, eller Exkludera för att ta bort inläggstypen från språkvägen helt.','Collapsible dump of all LF-owned entries in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts after adding a new language.'=>'Kollapsbar dump av alla LF-ägda poster i $wp_rewrite->extra_rules_top. Användbar för att diagnostisera 404-fel eller routingkonflikter efter att ha lagt till ett nytt språk.','One-click copy of a plain-text system summary covering all of the above sections. Paste this into a GitHub issue or support request so the full environment is visible at a glance.'=>'Enklickskopiering av en ren text-systemöversikt som täcker alla ovanstående avsnitt. Klistra in detta i ett GitHub-ärende eller supportbegäran så att hela miljön är synlig på en gång.','Found a bug or unexpected behaviour? Please open an issue on GitHub — include the Debug Info block above and a short description of what you expected vs. what happened.'=>'Hittade ett fel eller oväntat beteende? Öppna ett ärende på GitHub — inkludera Debug Info-blocket ovan och en kort beskrivning av vad du förväntade dig vs. vad som hände.','Open an issue →'=>'Öppna ett ärende →','Getting started'=>'Komma igång','Server setup (subdomain)'=>'Serverinställningar (subdomän)','Translation workflow'=>'Översättningsarbetsflöde','Language switcher'=>'Språkväxlare','WP-CLI reference'=>'WP-CLI-referens','Integration API'=>'Integrations-API','Documentation'=>'Dokumentation','Report an issue on GitHub'=>'Rapportera ett problem på GitHub','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','WordPress AI Client (WP 7.0+)'=>'WordPress AI-klient (WP 7.0+)','Meta Description, Excerpt Generator'=>'Meta-beskrivning, Sammanfattningsgenererare','Translation, Content Generator'=>'Översättning, Innehållsgenerator','Testing…'=>'Testar…','✓ Connection OK'=>'✓ Anslutning OK','✗ Failed:'=>'✗ Misslyckades:','No response from provider — check the error log for details.'=>'Ingen respons från leverantören — kontrollera felloggen för detaljer.','Network error — could not reach the WordPress AJAX endpoint.'=>'Nätverksfel — kunde inte nå WordPress AJAX-endpointen.','Translating a real post with this model…'=>'Översätter ett verkligt inlägg med denna modell…','preset'=>'förinställning','Loading…'=>'Läser in…','Installing…'=>'Installerar…','✓ Language installed.'=>'✓ Språk installerat.','✗ Error:'=>'✗ Fel:','Creating…'=>'Skapar…','✓ All templates created.'=>'✓ Alla mallar skapade.','Some templates could not be created.'=>'Vissa mallar kunde inte skapas.','Recreating…'=>'Återskapar…','✓ All templates recreated.'=>'✓ Alla mallar återskapade.','Some templates could not be recreated.'=>'Vissa mallar kunde inte återskapas.','This overwrites this template with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Detta ersätter denna mall med en ny kopia från det aktiva temat och förkastar alla anpassningar gjorda i Site Editor. Detta kan inte ångras. Fortsätta?','This overwrites every template with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Detta ersätter alla mallar med nya kopior från det aktiva temat och förkastar alla anpassningar gjorda i Site Editor. Detta kan inte ångras. Fortsätta?','✓ All parts recreated.'=>'✓ Alla delar återskapade.','Some parts could not be recreated.'=>'Vissa delar kunde inte återskapas.','This overwrites this template part with a fresh copy from the active theme, discarding any Site Editor customisations made to it. This cannot be undone. Continue?'=>'Detta ersätter denna malldel med en ny kopia från det aktiva temat och förkastar alla anpassningar gjorda i Site Editor. Detta kan inte ångras. Fortsätta?','This overwrites every template part with a fresh copy from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Detta ersätter alla malldelar med nya kopior från det aktiva temat och förkastar alla anpassningar gjorda i Site Editor. Detta kan inte ångras. Fortsätta?','✓ All parts created.'=>'✓ Alla delar skapade.','Some parts could not be created.'=>'Vissa delar kunde inte skapas.','✓ All translated.'=>'✓ Alla översatta.','Some translations failed.'=>'Vissa översättningar misslyckades.','Review carefully — links and slugs not updated.'=>'Granska noggrant — länkar och slugs är inte uppdaterade.','Fixing…'=>'Fixar…','✓ Links fixed.'=>'✓ Länkar fixade.','Some link fixes failed.'=>'Vissa länkfix misslyckades.','✓ Parts fixed.'=>'✓ Delar fixade.','Some part fixes failed.'=>'Vissa delfix misslyckades.','✓ Nav refs fixed.'=>'✓ Navigationsreferenser fixade.','Some nav ref fixes failed.'=>'Vissa navigationsreferensfix misslyckades.','✓ Pattern translated.'=>'✓ Mönster översatt.','Pattern translation failed.'=>'Mönsteröversättning misslyckades.','Hide'=>'Dölj','Re-create all templates'=>'Återskapa alla mallar','Re-create all parts'=>'Återskapa alla delar','This runs Re-create all templates, Re-create all parts, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time. It overwrites existing templates and parts with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template and part, which may take a while and may incur cost depending on your provider. Continue?'=>'Detta kör Återskapa alla mallar, Återskapa alla delar, Översätt allt, Fixa alla delar och Fixa alla länkar för vart och ett av dina {total} aktiva språk, ett språk i taget. Det ersätter befintliga mallar och delar med nya kopior från det aktiva temat (förkastar Site Editor-anpassningar) och översätter innehållet på nytt — inget av detta kan ångras. Översätt allt gör verkliga AI API-anrop för varje mall och del, vilket kan ta tid och kan medföra kostnader beroende på din leverantör. Fortsätta?','This runs Re-create all templates, Translate all, Fix all parts, and Fix all links for every one of your {total} active languages, one language at a time — template parts (headers, footers, etc.) are left untouched. It overwrites existing templates with fresh copies from the active theme (discarding Site Editor customisations) and re-translates content — none of this can be undone. Translate all makes real AI API calls for every template, which may take a while and may incur cost depending on your provider. Continue?'=>'Detta kör Återskapa alla mallar, Översätt allt, Fixa alla delar och Fixa alla länkar för vart och ett av dina {total} aktiva språk, ett språk i taget — malldelar (huvuden, fotnoter osv.) lämnas orörda. Det ersätter befintliga mallar med nya kopior från det aktiva temat (förkastar Site Editor-anpassningar) och översätter innehållet på nytt — inget av detta kan ångras. Översätt allt gör verkliga AI API-anrop för varje mall, vilket kan ta tid och kan medföra kostnader beroende på din leverantör. Fortsätta?','This runs Re-create all parts (headers, footers, and every other template part) for every one of your {total} active languages, one language at a time. It overwrites existing template parts with fresh copies from the active theme, discarding any Site Editor customisations made to them. This cannot be undone. Continue?'=>'Detta kör Återskapa alla delar (huvuden, fotnoter och alla andra malldelar) för vart och ett av dina {total} aktiva språk, ett språk i taget. Det ersätter befintliga malldelar med nya kopior från det aktiva temat och förkastar alla anpassningar gjorda i Site Editor. Detta kan inte ångras. Fortsätta?','Starting…'=>'Startar…','Processing {lang} ({index} of {total}) — {step}…'=>'Bearbetar {lang} ({index} av {total}) — {step}…','Cancelled.'=>'Avbruten.','{done} of {total} languages processed.'=>'{done} av {total} språk bearbetade.','⚠ Done with issues.'=>'⚠ Klart med problem.','✓ All {total} languages processed.'=>'✓ Alla {total} språk bearbetade.','Built-in preset instructions:'=>'Inbyggda förinställda instruktioner:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Inga inbyggda instruktioner — varje AI-funktion använder sina egna justerade standardinställningar. Fyll i fältet för anpassade instruktioner nedan för att lägga till dina egna regler för hela webbplatsen.','Modified'=>'Ändrad','edit'=>'redigera','No published posts found for the selected filters.'=>'Inga publicerade inlägg hittades för de valda filtren.','Just now'=>'Precis nyss','Score'=>'Poäng','Source title'=>'Källtitel','Multilingual SEO overview'=>'Översikt över flerspråkig SEO','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Poäng är en signal, inte ett avgörande. Viss innehåll är strukturellt begränsat — mycket korta sidor, landningssidor med lite kroppstext, eller sidor vars syfte är navigering snarare än information kan naturligtvis få lägre poäng. Använd denna översikt för att upptäcka äkta parity-gap mellan språk, inte för att jaga ett nummer.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'Detta är en WooCommerce-systemssida (butik, kundvagn, kassa etc.). Dess innehåll hanteras av WooCommerce — poängen speglar endast strukturella signaler, inte SEO-innehåll som användaren kan redigera.','Settings'=>'Inställningar','You do not have permission to manage these settings.'=>'Du har inte behörighet att hantera dessa inställningar.','Lingua Forge — Settings'=>'Lingua Forge — Inställningar','Settings saved.'=>'Inställningar sparade.','Save Settings'=>'Spara inställningar','Standard'=>'Standard','Technical / Scientific'=>'Tekniskt / Vetenskapligt','Legal / Compliance'=>'Juridiskt / Efterlevnad','Creative / Marketing'=>'Kreativt / Marknadsföring','Lingua Forge — AI Usage Statistics'=>'Lingua Forge — AI-användningsstatistik','Lingua Forge AI Usage Statistics'=>'Lingua Forge AI Användningsstatistik','Date'=>'Datum','Request count'=>'Antal begäranden','Full Article'=>'Full artikel','Introduction only'=>'Endast introduktion','Structured Outline'=>'Strukturerad disposition','Generate Content'=>'Generera innehåll','Hints'=>'Tips','Key points, ideas, or structure to build from…'=>'Huvudpunkter, idéer eller struktur att bygga från…','Tone'=>'Ton','Output'=>'Utdata','Generate Excerpt'=>'Generera utdrag','Generate Meta Description'=>'Generera meta-beskrivning','Translate Content'=>'Översätt innehåll','Mode'=>'Läge','Full post'=>'Fullt inlägg','Translate chunk'=>'Översätt del','Target Language'=>'Mål-språk','Text to translate'=>'Text att översätta','Paste a footnote, sentence, or any snippet here…'=>'Klistra in en fotnot, mening eller något annat här…','Also generate meta description'=>'Generera också meta-beskrivning','Translated Labels'=>'Översatta etiketter','Attribute label displayed in this language. Leave empty to use the default label.'=>'Etikett för attribut som visas på detta språk. Lämna tomt för att använda standardetiketten.','Translate all labels (AI)'=>'Översätt alla etiketter (AI)','Insufficient permissions.'=>'Otillräckliga behörigheter.','All labels already translated.'=>'Alla etiketter är redan översatta.','%d label(s) translated.'=>'%d etikett(er) översatta.','Translation failed. Check the browser console.'=>'Översättningen misslyckades. Kontrollera webbläsarens konsol.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Kan inte skriva till produkt %1$d: det är en översatt version (språk: %2$s)%3$s. Operativ data (pris, lager, SKU, dimensioner) måste uppdateras på källprodukten. Lös in produktens ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Translated Names'=>'Översatta namn','Name displayed in this language. Leave empty to use the source name.'=>'Namn som visas på detta språk. Lämna tomt för att använda källnamnet.','Translate all tags (AI)'=>'Översätt alla taggar (AI)','Translate all categories (AI)'=>'Översätt alla kategorier (AI)','Translate all %s terms (AI)'=>'Översätt alla %s-termer (AI)','Translate all terms (AI)'=>'Översätt alla termer (AI)','Invalid taxonomy.'=>'Ogiltig taxonomi.','No terms found.'=>'Inga termer hittades.','%d term(s) translated.'=>'%d term(er) översatta.','%d already translated — <a href="#" class="lf-force-translate">force retranslate</a>'=>'%d översatt redan — <a href="#" class="lf-force-translate">tvinga omöversättning</a>','%1$d translated, %2$d skipped.'=>'%1$d översatt, %2$d hoppade över.','Order placed in language: %s'=>'Beställning placerad på språk: %s','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Ogiltig API-nyckel — dubbelkolla nyckeln i AI-leverantörens inställningar.','Payment required — your account has no remaining credits.'=>'Betalning krävs — ditt konto har inga återstående krediter.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Tillträde förbjudet — ditt konto kan vara avstängt eller nyckeln saknar nödvändiga behörigheter.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Begränsad hastighet — för många förfrågningar skickade till leverantören; vänta en stund och försök igen.','Provider service temporarily unavailable — try again in a moment.'=>'Leverantörstjänsten är tillfälligt otillgänglig — försök igen om en stund.','Provider error (HTTP %1$d): %2$s'=>'Leverantörsfel (HTTP %1$d): %2$s','Unexpected provider error (HTTP %d).'=>'Oväntat leverantörsfel (HTTP %d).','No API key configured — enter your key in the AI Provider settings.'=>'Ingen API-nyckel konfigurerad — ange din nyckel i AI-leverantörens inställningar.','Network error — could not reach the provider: %s'=>'Nätverksfel — kunde inte nå leverantören: %s','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Inga krediter kvar — fyll på ditt OpenAI-konto på platform.openai.com/account/billing.','WordPress AI Client requires WordPress 7.0 or later.'=>'WordPress AI-klient kräver WordPress 7.0 eller senare.','No user message found in the message array.'=>'Ingen användarmeddelande hittades i meddelandearrayen.','No text-generation model is available. Configure an AI provider in Settings → Connectors.'=>'Ingen textgenereringsmodell är tillgänglig. Konfigurera en AI-leverantör i Inställningar → Connectors.','Too many AI requests. Please retry in %d seconds.'=>'För många AI-förfrågningar. Försök igen om %d sekunder.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Daglig AI-kvot uppnådd (%1$d förfrågningar). Återställs kl. %2$s UTC.','View Lingua Forge details'=>'Visa Lingua Forge detaljer','View details'=>'Visa detaljer','Visit plugin site'=>'Besök plugin-sidan','Lingua Forge update blocked: download host "%s" is not on the allowlist.'=>'Lingua Forge-uppdatering blockerad: nedladdningsvärdens "%s" är inte på tillåtlistan.','Lingua Forge update blocked: SHA-256 of the downloaded package does not match the manifest. The file may have been tampered with.'=>'Lingua Forge-uppdatering blockerad: SHA-256 för den nedladdade paketet matchar inte manifestet. Filen kan ha manipulerats.','Exclude from navigation menus'=>'Exkludera från navigationsmenyer','Apply to all language versions'=>'Tillämpa på alla språkversioner','Noindex (hide this language version from search engines)'=>'Noindex (dölj denna språkversion från sökmotorer)','%d language not yet linked'=>'%d språk är ännu inte kopplade' . "\0" . '%d språk är ännu inte kopplade','This is the source page. Footnotes are edited directly in the block editor.'=>'Detta är källsidan. Fotnoter redigeras direkt i blockredigeraren.','No source page linked yet.'=>'Ingen källsida kopplad än.','The source page has no footnotes.'=>'Källsidan har inga fotnoter.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Dessa fotnoter kommer från källsidan och visas här för referens. Lägg till dem på denna sida med blockredigeraren.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokaliserad(e) mall(ar) från temat &#8220;%2$s&#8221; finns bevarade i databasen men är för närvarande inaktiva. De kommer att bli aktiva igen om du aktiverar om det temat. För att föra över dina översättningar till det nya temat, generera dem på nytt via <strong>Inställningar → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for missing or out-of-sync featured images…'=>'Söker igenom inlägg efter saknade eller osynkroniserade destacerade bilder…','Re-scanning…'=>'Skannar om…','Scan failed: '=>'Skanning misslyckades: ','unknown error'=>'okänt fel','Scan request failed. Please try again.'=>'Skanningsförfrågan misslyckades. Försök igen.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Inga <strong>{lang}</strong> inlägg hittades. Se till att alla översatta inlägg har deras Språk-metadata inställt på <strong>{lang}</strong> i Språk-metaboxen.','✅ All <strong>{lang}</strong> featured images are already in sync with their source post. Scanned <strong>{scanned}</strong> post(s).'=>'✅ Alla <strong>{lang}</strong> utvalda bilder är redan synkroniserade med deras källinlägg. Skannade <strong>{scanned}</strong> inlägg.','Found <strong>{n}</strong> post(s) missing or out of sync with their source featured image, out of <strong>{scanned}</strong> scanned for <strong>{lang}</strong>.'=>'Hittade <strong>{n}</strong> inlägg som saknas eller är ur synk med sin källans destacerad bild, av <strong>{scanned}</strong> skannade för <strong>{lang}</strong>.','Post'=>'Inlägg','Current'=>'Aktuell','Source (EN)'=>'Källterm','None'=>'Ingen','Copy from source'=>'Kopiera från källa','Copying…'=>'Kopierar…','✅ Copied'=>'✅ Kopierat','❌ Failed'=>'❌ Misslyckades','Done — {done} of {total} post(s) fixed.'=>'Klart — {done} av {total} inlägg har fixats.','Fixing {n} / {total}…'=>'Fixar {n} / {total}…','Fix Featured Images'=>'Fix Featured Images','Featured Image Fixer'=>'Featured Image Fixer','Fix All'=>'Fixa alla','Re-scan'=>'Skanna om','Scanning posts for broken language links…'=>'Skannar inlägg för trasiga språk länkar…','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Inga trasiga länkar eller mallmissmatchningar hittades för <strong>{lang}</strong>. Skannade <strong>{scanned}</strong> inlägg och sidor — alla kontroller godkända. Malldelar (huvud, sidfot, sidopanel) ingår inte här — använd knappen Fix Template Parts för att kontrollera dessa separat.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatiskt rättbara länk(er)','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> länk(er) som kräver manuell granskning','and'=>'och','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Hittade {parts} över <strong>{total}</strong> av <strong>{scanned}</strong> skannade inlägg för <strong>{lang}</strong>.','link(s)'=>'länk(ar)','Fix'=>'Fix','✅ Fixed ({n})'=>'✅ Fikset ({n})','⚠ No changes — re-scan?'=>'⚠ Inga ändringar — skanna om?','⚠ No changes'=>'⚠ Inga ändringar','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hade inga ersättbara länkar — skanna om för att undersöka)','URL could not be mapped to a post — check the link target exists'=>'URL kunde inte mappas till ett inlägg — kontrollera att målet för länken finns','No {lang} translation registered (TRID missing)'=>'Ingen {lang} översättning registrerad (TRID saknas)','Translation found but permalink could not be generated'=>'Hittade översättning men permalänk kunde inte genereras','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> inaktiva sökväg(ar)','📍 Stale path (page moved)'=>'📍 Inaktiv sökväg (sidan flyttad)','{n} stale path(s)'=>'{n} inaktiva sökväg(ar)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> mallproblem','📄 Wrong template'=>'📄 Fel mall','Expected: {expected}'=>'Förväntat: {expected}','Current: {current}'=>'Aktuellt: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Mallen "{expected}" finns inte — skapa den i sidredigeraren först.','Fix Template'=>'Fixa mall','✅ Template fixed'=>'✅ Mall fixad','Internal Link Fixer'=>'Interna länkar-justerare','Language Switcher'=>'Språkväxlare','Displays the Lingua Forge language switcher.'=>'Visar Lingua Forges språkväxlare.','Display'=>'Visa','Language label'=>'Språklabel','Icon only'=>'Endast ikon','Icon + label'=>'Ikon + etikett','Dropdown direction'=>'Riktningsriktning för dropdown','Down'=>'